////////////////////////////////////////////////////////////////////////////////
//
// Filename:	rtl/core/prefetch.v
// {{{
// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
//
// Purpose:	This is a very simple instruction fetch approach.  It gets
//		one instruction at a time.  Future versions should pipeline
//	fetches and perhaps even cache results--this doesn't do that.  It
//	should, however, be simple enough to get things running.
//
//	The interface is fascinating.  The 'i_pc' input wire is just a
//	suggestion of what to load.  Other wires may be loaded instead. i_pc
//	is what must be output, not necessarily input.
//
//   20150919 -- Added support for the WB error signal.  When reading an
//	instruction results in this signal being raised, the pipefetch module
//	will set an illegal instruction flag to be returned to the CPU together
//	with the instruction.  Hence, the ZipCPU can trap on it if necessary.
//
//   20171020 -- Added a formal proof to prove that the module works.  This
//	also involved adding a req_addr register, and the logic associated
//	with it.
//
//   20171113 -- Removed the req_addr register, replacing it with a bus abort
//	capability.
//
// Creator:	Dan Gisselquist, Ph.D.
//		Gisselquist Technology, LLC
//
////////////////////////////////////////////////////////////////////////////////
// }}}
// Copyright (C) 2015-2025, Gisselquist Technology, LLC
// {{{
// This program is free software (firmware): you can redistribute it and/or
// modify it under the terms of the GNU General Public License as published
// by the Free Software Foundation, either version 3 of the License, or (at
// your option) any later version.
//
// This program is distributed in the hope that it will be useful, but WITHOUT
// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
// for more details.
//
// You should have received a copy of the GNU General Public License along
// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
// target there if the PDF file isn't present.)  If not, see
// <http://www.gnu.org/licenses/> for a copy.
// }}}
// License:	GPL, v3, as defined and found on www.gnu.org,
// {{{
//		http://www.gnu.org/licenses/gpl.html
//
////////////////////////////////////////////////////////////////////////////////
//
`default_nettype	none
// }}}
module	prefetch #(
		// {{{
		parameter		ADDRESS_WIDTH=30,	// Byte addr wid
					INSN_WIDTH=32,
					DATA_WIDTH=INSN_WIDTH,
		localparam		AW=ADDRESS_WIDTH,
					DW=DATA_WIDTH,
		parameter	[0:0]	OPT_ALIGNED = 1'b0,
		parameter	[0:0]	OPT_LITTLE_ENDIAN = 1'b1
		// }}}
	) (
		// {{{
		input	wire			i_clk, i_reset,
		// CPU interaction wires
		input	wire			i_new_pc, i_clear_cache,
						i_ready,
		// We ignore i_pc unless i_new_pc is true as well
		input	wire	[AW-1:0]	i_pc,
		output	reg			o_valid, // If output is valid
		output	reg			o_illegal, // bus err result
		output	reg [INSN_WIDTH-1:0]	o_insn,	// Insn read from WB
		output	reg	[AW-1:0]	o_pc,	// Byt addr of that insn
		// Wishbone outputs
		output	reg			o_wb_cyc, o_wb_stb,
		// verilator coverage_off
		output	wire			o_wb_we,	// == const 0
		// verilator coverage_on
		output	reg [AW-$clog2(DW/8)-1:0]	o_wb_addr,
		// verilator coverage_off
		output	wire	[DW-1:0]	o_wb_data,	// == const 0
		// verilator coverage_on
		// And return inputs
		input	wire			i_wb_stall, i_wb_ack, i_wb_err,
		input	wire	[DW-1:0]	i_wb_data
		// }}}
	);

	// Declare local variables
	// {{{
	reg			invalid;

	wire			r_valid;
	wire [DATA_WIDTH-1:0]	r_insn, i_wb_shifted;
	// }}}

	// These are kind of obligatory outputs when dealing with a bus, that
	// we'll set them here.  Nothing's going to pay attention to these,
	// though, this is primarily for form.
	assign	o_wb_we = 1'b0;
	assign	o_wb_data = {(DATA_WIDTH){1'b0}};

	// o_wb_cyc, o_wb_stb
	// {{{
	// Let's build it simple and upgrade later: For each instruction
	// we do one bus cycle to get the instruction.  Later we should
	// pipeline this, but for now let's just do one at a time.
	initial	o_wb_cyc = 1'b0;
	initial	o_wb_stb = 1'b0;
	always @(posedge i_clk)
	if ((i_reset || i_clear_cache)||(o_wb_cyc &&(i_wb_ack||i_wb_err)))
	begin
		// {{{
		// End any bus cycle on a reset, or a return ACK
		// or error.
		o_wb_cyc <= 1'b0;
		o_wb_stb <= 1'b0;
		// }}}
	end else if (!o_wb_cyc &&(
			// Start if the last instruction output was
			// accepted, *and* it wasn't a bus error
			// response
			(i_ready && !o_illegal && !r_valid)
			// Start if the last bus result ended up
			// invalid
			||(invalid)
			// Start on any request for a new address
			||i_new_pc))
	begin
		// {{{
		// Initiate a bus transaction
		o_wb_cyc <= 1'b1;
		o_wb_stb <= 1'b1;
		// }}}
	end else if (o_wb_cyc)
	begin
		// {{{
		// If our request has been accepted, then drop the
		// strobe line
		if (!i_wb_stall)
			o_wb_stb <= 1'b0;

		// Abort on new-pc
		// ... clear_cache  is identical, save that it will
		// immediately be followed by a new PC, so we don't
		// need to worry about that other than to drop
		// CYC and STB here.
		if (i_new_pc)
		begin
			o_wb_cyc <= 1'b0;
			o_wb_stb <= 1'b0;
		end
		// }}}
	end
	// }}}

	// invalid
	// {{{
	// If during the current bus request, a command came in from the CPU
	// that will invalidate the results of that request, then we need to
	// keep track of an "invalid" flag to remember that and so squash
	// the result.
	//
	initial	invalid = 1'b0;
	always @(posedge i_clk)
	if (i_reset || !o_wb_cyc)
		invalid <= 1'b0;
	else if (i_new_pc)
		invalid <= 1'b1;
	// }}}

	// The wishbone request address, o_wb_addr
	// {{{
	// The rule regarding this address is that it can *only* be changed
	// when no bus request is active.  Further, since the CPU is depending
	// upon this value to know what "PC" is associated with the instruction
	// it is processing, we can't change until either the CPU has accepted
	// our result, or it is requesting a new PC (and hence not using the
	// output).
	//
	initial	o_wb_addr= 0;
	always @(posedge i_clk)
	if (i_new_pc)
		o_wb_addr  <= i_pc[AW-1:$clog2(DATA_WIDTH/8)];
	else if (o_valid && i_ready && !r_valid)
		o_wb_addr  <= o_wb_addr + 1'b1;
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// (Optionally) shift the output word into place
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	// This only applies when the bus size doesn't match the instruction
	// word size.  Here, we only support bus sizes greater than the
	// instruction word size.
`ifdef	FORMAL
	wire	[DATA_WIDTH-1:0]	f_bus_word;
`endif

	generate if (DATA_WIDTH > INSN_WIDTH)
	begin : GEN_SUBSHIFT
		// {{{
		localparam	NSHIFT = $clog2(DATA_WIDTH/INSN_WIDTH);

		reg			rg_valid;
		reg [DATA_WIDTH-1:0]	rg_insn;
		reg	[NSHIFT:0]	r_count;
		reg	[NSHIFT-1:0]	r_shift;

		// rg_valid
		// {{{
		always @(posedge i_clk)
		if (i_reset || i_new_pc || i_clear_cache)
			rg_valid <= 1'b0;
		else if (r_count <= ((o_valid && i_ready) ? 1:0))
		begin
			rg_valid <= 1'b0;
			if (o_wb_cyc && i_wb_ack && !(&r_shift))
				rg_valid <= 1'b1;
		end
		// }}}

		// rg_insn
		// {{{
		always @(posedge i_clk)
		if (i_wb_ack && (r_count <= ((o_valid && i_ready) ? 1:0)))
		begin
			rg_insn <= i_wb_data;
			if (OPT_LITTLE_ENDIAN)
			begin
				rg_insn <= i_wb_shifted >> INSN_WIDTH;
			end else begin
				rg_insn <= i_wb_shifted << INSN_WIDTH;
			end
		end else if (o_valid && i_ready)
		begin
			if (OPT_LITTLE_ENDIAN)
				rg_insn <= rg_insn >> INSN_WIDTH;
			else
				rg_insn <= rg_insn << INSN_WIDTH;
		end
		// }}}

		// r_count
		// {{{
		always @(posedge i_clk)
		if (i_reset || i_new_pc || i_clear_cache)
			r_count <= 0;
		// Verilator lint_off CMPCONST
		else if (o_valid && i_ready && r_valid)
		// Verilator lint_on  CMPCONST
			r_count <= r_count - 1;
		else if (o_wb_cyc && i_wb_ack)
		begin
			// if (OPT_LITTLE_ENDIAN)
			r_count <= { 1'b0, ~r_shift };
		end
`ifdef	FORMAL
		always @(*)
		if (!i_reset)
		begin
			assert(r_valid == (r_count > 0));
			assert(r_count <= (1<<NSHIFT));
			if (r_valid)
			begin
				assert(!o_wb_cyc);
				assert(r_shift == 0);
			end else if (!i_new_pc && !i_clear_cache && !o_illegal)
				assert(invalid || o_valid || o_wb_cyc);
		end
`endif
		// }}}

		// r_shift
		// {{{
		always @(posedge i_clk)
		if (i_reset)
			r_shift <= 0;
		else if (i_new_pc)
			r_shift <= i_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)];
		else if (o_wb_cyc && (i_wb_ack || i_wb_err))
			r_shift <= 0;

`ifdef	FORMAL
		always @(*)
		if (!i_reset && r_shift > 0)
			assert(!o_valid && !r_valid);
`endif
		// }}}

		assign	r_valid = rg_valid;

		assign	r_insn  = rg_insn;
		if (OPT_LITTLE_ENDIAN)
		begin : GEN_LIL_ENDIAN_SHIFT
			assign	i_wb_shifted = i_wb_data >> (r_shift * INSN_WIDTH);
		end else begin : GEN_BIG_ENDIAN_SHIFT
			assign	i_wb_shifted = i_wb_data << (r_shift * INSN_WIDTH);
		end

		// Keep Verilator happy
		// {{{
		// Verilator coverage_off
		// Verilator lint_off UNUSED
		wire	unused_shift;
		assign	unused_shift = &{ 1'b0,
				r_insn[DATA_WIDTH-1:INSN_WIDTH],
				i_wb_shifted[DATA_WIDTH-1:INSN_WIDTH] };
		// Verilator lint_on  UNUSED
		// Verilator coverage_on
		// }}}
`ifdef	FORMAL
		assign	f_bus_word = rg_insn << ((r_count-1)* INSN_WIDTH);
		always @(*)
		if (!i_reset && r_valid)
		begin
			assert(o_valid);
			assert(r_shift == 0);
			// assert((r_count + o_pc[NSHIFT-1:0]) == ((1<<NSHIFT)-1));
			assert((r_count + o_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)])
				== ((1<<NSHIFT)-1));
		end else if (!i_reset && o_wb_cyc && !invalid)
		begin
			assert(r_shift == o_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)]);
		end
`endif
		// }}}
	end else begin : NO_SUBSHIFT
		// {{{
		assign	r_valid = 1'b0;
		assign	r_insn  = {(INSN_WIDTH){1'b0}};
		assign	i_wb_shifted = i_wb_data;
`ifdef	FORMAL
		assign	f_bus_word = 0;
`endif
		// Verilator lint_off UNUSED
		wire	unused_shift;
		assign	unused_shift = &{ 1'b0, OPT_LITTLE_ENDIAN };
		// Verilator lint_on  UNUSED
		// }}}
	end endgenerate
	// }}}

	// o_insn
	// {{{
	// The instruction returned is given by the data returned from the bus.
	always @(posedge i_clk)
	if (i_wb_ack)
	begin
		if (OPT_LITTLE_ENDIAN)
			o_insn <= i_wb_shifted[INSN_WIDTH-1:0];
		else
			o_insn <= i_wb_shifted[DW-1:DW-INSN_WIDTH];
	end else if (i_ready && (DATA_WIDTH != INSN_WIDTH))
	begin
		if (OPT_LITTLE_ENDIAN)
			o_insn <= r_insn[INSN_WIDTH-1:0];
		else
			o_insn <= r_insn[DW-1:DW-INSN_WIDTH];
	end
`ifdef	FORMAL
	always @(posedge i_clk) if (!i_reset && o_valid) assert(!i_wb_ack);
`endif
	// }}}

	// o_valid, o_illegal
	// {{{
	// Finally, the flags associated with the prefetch.  The rule is that
	// if the output represents a return from the bus, then o_valid needs
	// to be true.  o_illegal will be true any time the last bus request
	// resulted in an error.  o_illegal is only relevant to the CPU when
	// o_valid is also true, hence o_valid will be true even in the case
	// of a bus error in our request.
	//
	initial o_valid   = 1'b0;
	initial o_illegal = 1'b0;
	always @(posedge i_clk)
	if (i_reset || i_new_pc || i_clear_cache)
	begin
		// On any reset, request for a new PC (i.e. a branch),
		// or a request to clear our cache (i.e. the data
		// in memory may have changed), we invalidate any
		// output.
		o_valid   <= 1'b0;
		o_illegal <= 1'b0;
	end else if (o_wb_cyc &&(i_wb_ack || i_wb_err))
	begin
		// Otherwise, at the end of our bus cycle, the
		// answer will be valid.  Well, not quite.  If the
		// user requested something mid-cycle (i_new_pc)
		// or (i_clear_cache), then we'll have to redo the
		// bus request, so we aren't valid.
		//
		o_valid   <= 1'b1;
		o_illegal <= ( i_wb_err);
	end else if (i_ready)
	begin
		// Once the CPU accepts any result we produce, clear
		// the valid flag, lest we send two identical
		// instructions to the CPU.
		//
		o_valid <= r_valid;
		//
		// o_illegal doesn't change ... that way we don't
		// access the bus again until a new address request
		// is given to us, via i_new_pc, or we are asked
		//  to check again via i_clear_cache
		//
		// o_illegal <= (!i_ready);
	end
	// }}}

	// The o_pc output shares its value with the (last) wishbone address
	// {{{
	generate if (OPT_ALIGNED && (INSN_WIDTH == DATA_WIDTH))
	begin : ALIGNED_PF_PC
		// {{{
		always @(*)
			o_pc = { o_wb_addr,
				{($clog2(DATA_WIDTH/8)){1'b0}} };
		// }}}
	end else begin : GENERATE_PF_PC
		// {{{
		initial	o_pc = 0;
		always @(posedge i_clk)
		if (i_new_pc)
			o_pc <= i_pc;
		else if (o_valid && i_ready)
		begin
			o_pc <= 0;
			o_pc[AW-1:$clog2(INSN_WIDTH/8)]
				<= o_pc[AW-1:$clog2(INSN_WIDTH/8)] + 1;
		end
		// }}}
	end endgenerate
`ifdef	FORMAL
	always @(*)
	if (!i_reset && !o_illegal && !i_new_pc && !i_clear_cache)
		assert(o_pc[AW-1:$clog2(DATA_WIDTH/8)] == o_wb_addr);
`endif
	// }}}

	// Make verilator happy
	// {{{
	// verilator coverage_off
	// verilator lint_off UNUSED
	wire	unused;
	assign	unused = &{ 1'b0, i_pc[1:0] };
	// verilator lint_on  UNUSED
	// verilator coverage_on
	// }}}
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
//
// Formal properties
// {{{
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
`ifdef	FORMAL
	// Declarations
	// {{{
	localparam	F_LGDEPTH=2;
	reg	f_past_valid;
	wire	[(F_LGDEPTH-1):0]	f_nreqs, f_nacks,
					f_outstanding;
	reg	[AW-$clog2(DATA_WIDTH/8)-1:0]	f_req_addr;
	wire	[AW-$clog2(DATA_WIDTH/8)-1:0]	f_next_wb_addr;

	// Keep track of a flag telling us whether or not $past()
	// will return valid results
	initial	f_past_valid = 1'b0;
	always @(posedge i_clk)
		f_past_valid <= 1'b1;
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Bus interface properties
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	fwb_master #(
		// {{{
		.AW(AW-$clog2(DATA_WIDTH/8)), .DW(DW),.F_LGDEPTH(F_LGDEPTH),
		.F_MAX_REQUESTS(1), .F_OPT_SOURCE(1),
		.F_OPT_RMW_BUS_OPTION(0),
		.F_OPT_DISCONTINUOUS(0)
		// }}}
	) f_wbm(
		// {{{
		.i_clk(i_clk), .i_reset(i_reset),
		.i_wb_cyc(o_wb_cyc), .i_wb_stb(o_wb_stb), .i_wb_we(o_wb_we),
		.i_wb_addr(o_wb_addr), .i_wb_data(o_wb_data),
				.i_wb_sel({($clog2(DW/8)){1'b0}}),
		.i_wb_ack(i_wb_ack), .i_wb_stall(i_wb_stall),
			.i_wb_idata(i_wb_data), .i_wb_err(i_wb_err),
		.f_nreqs(f_nreqs), .f_nacks(f_nacks),
			.f_outstanding(f_outstanding)
		// }}}
	);

	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// CPU interface properties
	// {{{
	/////////////////////////////////////////////////
	//
	//
	wire			f_const_illegal;
	wire	[AW-1:0]	f_const_addr;
	wire	[DW-1:0]	f_const_insn;
	wire	[AW-1:0]	f_address;

	ffetch #(
		// {{{
		.ADDRESS_WIDTH(AW-$clog2(INSN_WIDTH/8)),
		.OPT_ALIGNED(OPT_ALIGNED),
		.INSN_WIDTH(INSN_WIDTH)
		// }}}
	) cpu(
		// {{{
		.i_clk(i_clk), .i_reset(i_reset),
		.cpu_new_pc(i_new_pc), .cpu_clear_cache(i_clear_cache),
		.cpu_pc(i_pc), .pf_valid(o_valid), .cpu_ready(i_ready),
		.pf_pc(o_pc), .pf_insn(o_insn), .pf_illegal(o_illegal),
		.fc_pc(f_const_addr), .fc_illegal(f_const_illegal),
		.fc_insn(f_const_insn), .f_address(f_address)
		// }}}
	);

	always @(*)
	if (!i_reset && !i_new_pc && !i_clear_cache && !o_illegal)
		assert(f_address == o_pc);

	always @(*)
	if (o_illegal)
		assert(!o_wb_cyc);

	//
	//
	// Let's make some assumptions about how long it takes our
	// phantom bus and phantom CPU to respond.
	//
	// These delays need to be long enough to flush out any potential
	// errors, yet still short enough that the formal method doesn't
	// take forever to solve.
	//
	localparam	F_CPU_DELAY = 4;
	reg	[4:0]	f_cpu_delay;
	// First, let's assume that any response from the bus comes back
	// within F_WB_DELAY clocks

		// Here's our delay assumption: We'll assume that the
	// wishbone will always respond within F_WB_DELAY clock ticks
	// of the beginning of any cycle.
	//
	// This includes both dropping the stall line, as well as
	// acknowledging any request.  While this may not be
	// a reasonable assumption for a piped master, it should
	// work here for us.

	// Count the number of clocks it takes the CPU to respond to our
	// instruction.
	always @(posedge i_clk)
	// If no instruction is ready, then keep our counter at zero
	if ((i_reset)||(!o_valid)||(i_ready))
		f_cpu_delay <= 0;
	else
		// Otherwise, count the clocks the CPU takes to respond
		f_cpu_delay <= f_cpu_delay + 1'b1;

`ifdef	PREFETCH
	// Only *assume* that we are less than F_CPU_DELAY if we are not
	// integrated into the CPU
	always @(posedge i_clk)
		assume(f_cpu_delay < F_CPU_DELAY);
`endif
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Assertions about our outputs
	// {{{
	/////////////////////////////////////////////////
	//
	// Assertions about our wishbone control outputs first
	// Prefetches don't write
	always @(*)
		assert(!o_wb_we);

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(f_past_valid))
			&&($past(i_clear_cache,2))
			&&($past(o_wb_cyc,2)))
		// Make sure any clear-cache transaction is aborted,
		// *and* that no valid instructions get sent to the
		// CPU
		assert((!$past(o_wb_cyc))||(!o_wb_cyc));

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(o_valid && !r_valid))&&(o_valid))
		assert(o_wb_addr == $past(o_wb_addr));

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(!i_reset && !i_clear_cache))&&($past(invalid)))
		assert(o_wb_cyc);

	// Any time the CPU accepts an instruction, assert that on the
	// valid line will be low on the next clock
	always @(posedge i_clk)
	if ((f_past_valid)&&($past(o_valid && i_ready && !r_valid)))
		assert(!o_valid);

	// Since we only change our output on a response from the bus, we
	// need to insist that the item has been read by the CPU before
	// we go looking/asking for a next value.
	//
	// This routine should never be requesting a new instruction when
	// one is valid--lest the CPU never accept the old instruction and we
	// have nothing to do with the data when the bus request returns.
	always @(*)
	if (o_wb_cyc)
		assert(!o_valid && !r_valid);

	// If we just got a valid instruction from the wishbone, assert that
	// the instruction is listed as valid on the next instruction cycle
	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))
		&&($past(o_wb_cyc))
		&&($past(!i_clear_cache))
		&&($past(i_wb_ack))&&(!$past(i_wb_err)))
	begin
		if (!invalid)
			assert(o_valid);
	end

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(i_clear_cache)))
		assert(!o_valid);

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(f_past_valid))
			&&($past(i_clear_cache,2))
			&&($past(o_wb_cyc,2)))
		// Make sure any clear-cache transaction is aborted,
		// *and* that no valid instructions get sent to the
		// CPU
		assert(!o_valid);

	//
	// Assertions about our return responses
	//
	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))
			&&(!$past(i_new_pc))&&(!$past(i_clear_cache))
			&&($past(o_valid))&&(!$past(i_ready)))
		assert(o_valid == $past(o_valid));

//	always @(posedge i_clk)
//	if ((f_past_valid)&&($past(o_valid))&&(o_valid))
//	begin
//		assert($stable(o_pc));
//		assert($stable(o_insn));
//		assert($stable(o_illegal));
//	end

	//
	// The o_illegal line is the one we use to remind us not to go
	// back and retry the last value if it returned a bus error.  Hence,
	// let's assert that this line stays constant any time o_wb_cyc
	// is low, and we haven't received any new requests.
	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))
			&&(!$past(i_new_pc))&&(!$past(i_clear_cache))
			&&($past(!o_wb_cyc)))
		assert(o_illegal == $past(o_illegal));


	//
	//
	// Let's examine whether or not we "walk" though PC addresses one
	// at a time like we expect.
	//

	// f_req_addr
	// {{{
	initial	f_req_addr = 0;
	always @(posedge i_clk)
	if (i_new_pc)
		f_req_addr <= i_pc[AW-1:$clog2(DATA_WIDTH/8)];
	else if (!invalid && o_wb_cyc && i_wb_ack && !i_wb_err && !r_valid)
		f_req_addr <= f_req_addr + 1'b1;

	assign	f_next_wb_addr = o_wb_addr + 1;
	// }}}

	// Let's also keep the formal methods on track.  Any time we are
	// requesting a value, it should either be from the req_addr, or if
	// not a new value should've come in rendering this one invalid.
	always @(posedge i_clk)
	if (o_wb_cyc)
	begin
		assert(invalid ||(f_req_addr == o_wb_addr));

		// This isn't good enough for induction, so we'll need to
		// constrain this further
	end else if (!o_valid && !i_new_pc && !i_reset && !i_clear_cache)
		assert(o_illegal || f_req_addr == o_wb_addr);
	else if (!i_reset && r_valid)
		assert(f_req_addr == f_next_wb_addr);

	// In this version, invalid should only ever be high for one cycle.
	// CYC should be high on the cycle following--if ever.
	always @(posedge i_clk)
	if ((f_past_valid)&&($past(invalid)))
		assert(!invalid);
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Contract checking
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	wire	f_this_addr, f_this_pc, f_this_req, f_this_data;
	reg	f_addr_pending;
	reg	f_insn_pending;
	(* anyconst *)	reg	[DATA_WIDTH-1:0]	f_const_bus_word;

	assign	f_this_addr = (o_wb_addr ==   f_const_addr[AW-1:$clog2(DW/8)]);
	assign	f_this_pc   = (o_pc[AW-1:$clog2(DW/8)]== f_const_addr[AW-1:$clog2(DW/8)]);
	assign	f_this_req  = (i_pc[AW-1:$clog2(DW/8)]== f_const_addr[AW-1:$clog2(DW/8)]);
	assign	f_this_data = (i_wb_data ==   f_const_bus_word);

	generate if (DATA_WIDTH > INSN_WIDTH)
	begin : F_CHECK_SHIFTED_WORD
		// {{{
		wire	[DW-1:0]	f_shifted_insn;
		localparam		IW = INSN_WIDTH;

		if (OPT_LITTLE_ENDIAN)
		begin
			assign	f_shifted_insn = f_const_bus_word
			>> (f_const_addr[$clog2(DW/8)-1:$clog2(IW/8)] * IW);
			always @(*)
				assume(f_shifted_insn[IW-1:0] == f_const_insn);

		end else begin
			assign	f_shifted_insn = f_const_bus_word
			<< (f_const_addr[$clog2(DW/8)-1:$clog2(IW/8)] * IW);

			always @(*)
				assume(f_shifted_insn[DW-1:DW-IW]
							== f_const_insn);

		end
		// }}}
	end else begin
		// {{{
		always @(*)
			assume(f_const_bus_word == f_const_insn);
		// }}}
	end endgenerate

	// f_addr_pending
	// {{{
	initial	f_addr_pending = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		f_addr_pending <= 1'b0;
	else if (!o_wb_cyc)
		f_addr_pending <= 1'b0;
	else if ((o_wb_stb)&&(f_this_addr))
	begin
		if ((!i_wb_ack)&&(!i_wb_err))
			f_addr_pending <= 1'b1;
	end
	// }}}

	// 1. Assume the correct response for the given address
	// {{{
	always @(*)
	if ((o_wb_stb)&&(f_this_addr)&&(!i_wb_stall))
	begin
		if (!f_const_illegal)
		begin
			assume(!i_wb_err);
		end else
			assume(!i_wb_ack);
		if (i_wb_ack)
			assume(f_this_data);
	end else if ((o_wb_cyc)&&(f_addr_pending))
	begin
		if (!f_const_illegal)
		begin
			assume(!i_wb_err);
		end else
			assume(!i_wb_ack);
		if (i_wb_ack)
			assume(f_this_data);
	end
	// }}}

	// f_insn_pending
	// {{{
	initial	f_insn_pending = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		f_insn_pending <= 1'b0;
	else if (i_clear_cache)
		f_insn_pending <= 1'b0;
	else if (i_new_pc && f_this_req)
		f_insn_pending <= 1'b1;
	else if ((o_valid)||(i_new_pc))
		f_insn_pending <= 1'b0;
	// }}}

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(o_wb_cyc))&&(o_wb_cyc)&&(f_insn_pending))
		assert(f_this_pc);

	always @(posedge i_clk)
	if (((f_past_valid)&&($past(o_wb_cyc))&&($past(f_insn_pending)))
		&&(!$past(i_reset))&&(!$past(i_clear_cache))
		&&(!$past(i_new_pc)))
	begin
		if(!o_wb_cyc)
			assert(o_valid && f_this_pc);
	end

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(o_wb_cyc))&&(!o_wb_cyc))
		assert(!f_insn_pending);

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(o_wb_cyc))&&(o_wb_cyc)&&(f_this_addr))
		assert(f_addr_pending);

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(o_wb_cyc))&&(f_insn_pending))
		assert(f_this_addr);
	// }}}

	// Make Verilator happy
	// {{{
	// Verilator lint_off UNUSED
	wire	unused_formal;
	assign	unused_formal = &{ 1'b0, f_nreqs, f_nacks, f_outstanding,
			f_const_addr[1:0] };
	// Verilator lint_on  UNUSED
	// }}}
`endif
// }}}
endmodule
//
// Usage:	(this)	(mid)	(past)
//    Cells	167	230	175
//	FDRE	 67	 97	 69
//	LUT1	  1	  1	  1
//	LUT2	  1	  3	  3
//	LUT3	 31	 63	 33
//	LUT4	  5	  3	  3
//	LUT5	  1	  3	  3
//	LUT6	  2	  1	  3
//	MUXCY	 29	 29	 31
//	XORCY	 30	 30	 32

content.content:
1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/dblfetch.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	This is one step beyond the simplest instruction fetch,
8	//		prefetch.v.  dblfetch.v uses memory pipelining to fetch two
9	//	(or more) instruction words in one bus cycle.  If the CPU consumes
10	//	either of these before the bus cycle completes, a new request will be
11	//	made of the bus.  In this way, we can keep the CPU filled in spite
12	//	of a (potentially) slow memory operation.  The bus request will end
13	//	when both requests have been sent and both result locations are empty.
14	//
15	//	This routine is designed to be a touch faster than the single
16	//	instruction prefetch (prefetch.v), although not as fast as the
17	//	prefetch and cache approach found elsewhere (pfcache.v).
18	//
19	//	20180222: Completely rebuilt.
20	//
21	// Creator:	Dan Gisselquist, Ph.D.
22	//		Gisselquist Technology, LLC
23	//
24	////////////////////////////////////////////////////////////////////////////////
25	// }}}
26	// Copyright (C) 2017-2025, Gisselquist Technology, LLC
27	// {{{
28	// This program is free software (firmware): you can redistribute it and/or
29	// modify it under the terms of the GNU General Public License as published
30	// by the Free Software Foundation, either version 3 of the License, or (at
31	// your option) any later version.
32	//
33	// This program is distributed in the hope that it will be useful, but WITHOUT
34	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
35	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
36	// for more details.
37	//
38	// You should have received a copy of the GNU General Public License along
39	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
40	// target there if the PDF file isn't present.)  If not, see
41	// <http://www.gnu.org/licenses/> for a copy.
42	// }}}
43	// License:	GPL, v3, as defined and found on www.gnu.org,
44	// {{{
45	//		http://www.gnu.org/licenses/gpl.html
46	//
47	////////////////////////////////////////////////////////////////////////////////
48	//
49	`default_nettype	none
50	// }}}
51	module	dblfetch #(
52			// {{{
53			parameter		ADDRESS_WIDTH=30,	// Byte addr
54			parameter		INSN_WIDTH=32,
55			parameter		DATA_WIDTH = INSN_WIDTH,
56			localparam		AW=ADDRESS_WIDTH,
57						DW=DATA_WIDTH,
58			parameter	[0:0]	OPT_LITTLE_ENDIAN = 1'b1
59			// }}}
60		) (
61			// {{{
62			input	wire			i_clk, i_reset,
63			// CPU signals--from the CPU
64			input	wire			i_new_pc, i_clear_cache,i_ready,
65			input	wire	[AW-1:0]	i_pc,
66			// ... and in return
67			output	reg			o_valid,
68			output	reg			o_illegal,
69			output	reg [INSN_WIDTH-1:0]	o_insn,
70			output	reg	[AW-1:0]	o_pc,
71			// Wishbone outputs
72			output	reg			o_wb_cyc, o_wb_stb,
73			// verilator coverage_off
74			output	wire			o_wb_we,
75			// verilator coverage_on
76			output	reg [AW-$clog2(DW/8)-1:0] o_wb_addr,
77			// verilator coverage_off
78			output	wire	[DW-1:0]	o_wb_data,
79			// verilator coverage_on
80			// And return inputs
81			input	wire			i_wb_stall, i_wb_ack, i_wb_err,
82			input	wire	[DW-1:0]	i_wb_data
83			// }}}
84		);
85	
86		// Local declarations
87		// {{{
88		wire			last_stb;
89		reg			invalid_bus_cycle;
90	
91		reg	[(DW-1):0]	cache_word;
92		reg			cache_valid;
93		reg	[1:0]		inflight;
94		reg			cache_illegal;
95	
96		wire				r_valid;
97		wire	[DATA_WIDTH-1:0]	r_insn, i_wb_shifted;
98		// }}}
99	
100		assign	o_wb_we = 1'b0;
101		assign	o_wb_data = {(DATA_WIDTH){1'b0}};
102	
103		// o_wb_cyc, o_wb_stb
104		// {{{
105		initial	o_wb_cyc = 1'b0;
106		initial	o_wb_stb = 1'b0;
107		always @(posedge i_clk)
108		if (i_reset || i_clear_cache || (o_wb_cyc && i_wb_err))
109		begin : RESET_ABORT
110			// {{{
111			o_wb_cyc <= 1'b0;
112			o_wb_stb <= 1'b0;
113			// }}}
114		end else if (o_wb_cyc)
115		begin : END_CYCLE
116			// {{{
117			if (!o_wb_stb || !i_wb_stall)
118				o_wb_stb <= (!last_stb);
119	
120			// Relase the bus on the second ack
121			if ((!o_wb_stb || !i_wb_stall) && last_stb
122				&& inflight + (o_wb_stb ? 1:0) == (i_wb_ack ? 1:0))
123			begin
124				o_wb_cyc <= 1'b0;
125				o_wb_stb <= 1'b0;
126			end
127	
128			if (i_new_pc) // || i_clear_cache)
129				{ o_wb_cyc, o_wb_stb } <= 2'b0;
130			// }}}
131		end else if ((i_new_pc || invalid_bus_cycle)
132			||(o_valid && i_ready && !r_valid && !cache_illegal))
133		begin : START_CYCLE
134			// {{{
135			// Initiate a bus cycle if ... the last bus cycle was
136			// aborted (bus error or new_pc), we've been given a
137			// new PC to go get, or we just exhausted our one
138			// instruction cache
139			o_wb_cyc <= 1'b1;
140			o_wb_stb <= 1'b1;
141			// }}}
142		end
143		// }}}
144	
145		// inflight
146		// {{{
147		initial	inflight = 2'b00;
148		always @(posedge i_clk)
149		if (!o_wb_cyc)
150			inflight <= 2'b00;
151		else begin
152			case({ (o_wb_stb && !i_wb_stall), i_wb_ack })
153			2'b01:	inflight <= inflight - 1'b1;
154			2'b10:	inflight <= inflight + 1'b1;
155			// If neither ack nor request, then no change.  Likewise
156			// if we have both an ack and a request, there's no change
157			// in the number of requests in flight.
158			default: begin end
159			endcase
160		end
161		// }}}
162	
163		// last_stb
164		// {{{
165		// assign last_stb = (inflight != 2'b00)||(o_valid&& (!i_ready||r_valid));
166		assign	last_stb = (!o_wb_stb||!i_wb_stall)&&(inflight
167			+ (o_wb_stb ? 1:0)
168			+ (o_valid&&(!i_ready || r_valid)) >= 2'b10);
169		// }}}
170	
171		// invalid_bus_cycle
172		// {{{
173		initial	invalid_bus_cycle = 1'b0;
174		always @(posedge i_clk)
175		if (i_reset)
176			invalid_bus_cycle <= 1'b0;
177		else if (o_wb_cyc && i_new_pc)
178			invalid_bus_cycle <= 1'b1;
179		else if (!o_wb_cyc)
180			invalid_bus_cycle <= 1'b0;
181		// }}}
182	
183		// o_wb_addr
184		// {{{
185		initial	o_wb_addr = {(AW-$clog2(DATA_WIDTH/8)){1'b1}};
186		always @(posedge i_clk)
187		if (i_new_pc)
188			o_wb_addr <= i_pc[AW-1:$clog2(DATA_WIDTH/8)];
189		// else if (i_clear_cache)
190		//	o_wb_addr <= o_pc[AW-1:$clog2(DATA_WIDTH/8)];
191		else if (o_wb_stb && !i_wb_stall)
192			o_wb_addr <= o_wb_addr + 1'b1;
193		// }}}
194	
195		////////////////////////////////////////////////////////////////////////
196		//
197		// Now for the immediate output word to the CPU
198		// {{{
199		////////////////////////////////////////////////////////////////////////
200		//
201		//
202	
203		// This only applies when the bus size doesn't match the instruction
204		// word size.  Here, we only support bus sizes greater than the
205		// instruction word size.
206	`ifdef	FORMAL
207		wire	[DATA_WIDTH-1:0]	f_bus_word;
208	`endif
209	
210		generate if (DATA_WIDTH > INSN_WIDTH)
211		begin : GEN_SUBSHIFT
212			// {{{
213			localparam	NSHIFT = $clog2(DATA_WIDTH/INSN_WIDTH);
214	
215			reg			rg_valid;
216			reg [DATA_WIDTH-1:0]	rg_insn;
217			reg	[NSHIFT:0]	r_count;
218			reg	[NSHIFT-1:0]	r_shift;
219	
220			// rg_valid
221			// {{{
222			always @(posedge i_clk)
223			if (i_reset || i_new_pc) // || i_clear_cache)
224				rg_valid <= 1'b0;
225			else if (r_valid)
226				rg_valid <= !i_ready || (r_count > 1);
227			else if (!o_valid || i_ready)
228			begin
229				rg_valid <= 1'b0;
230				if (cache_valid)
231					rg_valid <= 1'b1;
232				if (o_wb_cyc && i_wb_ack && !(&r_shift))
233					rg_valid <= 1'b1;
234			end
235			// }}}
236	
237			// rg_insn
238			// {{{
239			always @(posedge i_clk)
240			if (!o_valid || i_ready)
241			begin
242				if (cache_valid && !r_valid)
243				begin
244					if (OPT_LITTLE_ENDIAN)
245						rg_insn <= cache_word >> INSN_WIDTH;
246					else
247						rg_insn <= cache_word << INSN_WIDTH;
248				end else if (i_wb_ack && !r_valid)
249				begin
250					rg_insn <= i_wb_data;
251					if (OPT_LITTLE_ENDIAN)
252						rg_insn <= i_wb_shifted >> INSN_WIDTH;
253					else
254						rg_insn <= i_wb_shifted << INSN_WIDTH;
255				end else begin
256					if (OPT_LITTLE_ENDIAN)
257						rg_insn <= rg_insn >> INSN_WIDTH;
258					else
259						rg_insn <= rg_insn << INSN_WIDTH;
260				end
261			end
262			// }}}
263	
264			// r_count
265			// {{{
266			always @(posedge i_clk)
267			if (i_reset || i_new_pc) // || i_clear_cache)
268				r_count <= 0;
269			else if (o_valid && i_ready && r_valid)
270			begin
271				r_count <= r_count - 1;
272			end else if (!o_valid || (i_ready && !r_valid))
273			begin
274				if (cache_valid)
275					r_count <= { 1'b0, {(NSHIFT){1'b1}} };
276				else if (o_wb_cyc && i_wb_ack)
277					r_count <= { 1'b0, ~r_shift };
278			end
279	`ifdef	FORMAL
280			always @(*)
281			if (!i_reset && !i_new_pc && !i_clear_cache)
282			begin
283				if (!o_valid)
284					assert(!r_valid);
285				assert(r_valid == (r_count > 0));
286				assert(r_count <= (1<<NSHIFT));
287				if (r_valid)
288				begin
289					assert(!cache_valid || !o_wb_cyc);
290					assert(r_shift == 0);
291				end else if (!i_new_pc && !i_clear_cache && !o_illegal)
292					assert(invalid_bus_cycle || o_valid || o_wb_cyc);
293			end
294	`endif
295			// }}}
296	
297			// r_shift
298			// {{{
299			always @(posedge i_clk)
300			if (i_new_pc)
301				r_shift <= i_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)];
302			// else if (i_clear_cache)
303			//	r_shift <= o_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)];
304			else if (o_wb_cyc && (i_wb_ack || i_wb_err))
305				r_shift <= 0;
306	
307	`ifdef	FORMAL
308			always @(*)
309			if (!i_reset && r_shift > 0)
310				assert(!o_valid && !r_valid);
311	`endif
312			// }}}
313	
314			assign	r_valid = rg_valid;
315			assign	r_insn  = rg_insn;
316			if (OPT_LITTLE_ENDIAN)
317			begin : GEN_LITTLE_ENDIAN_SHIFT
318				assign	i_wb_shifted = i_wb_data >> (r_shift * INSN_WIDTH);
319			end else begin : GEN_BIGENDIAN_SHIFT
320				assign	i_wb_shifted = i_wb_data << (r_shift * INSN_WIDTH);
321			end
322	
323			// Keep Verilator happy
324			// {{{
325			// Verilator lint_off UNUSED
326			wire	unused_shift;
327			assign	unused_shift = &{ 1'b0,
328					r_insn[DATA_WIDTH-1:INSN_WIDTH],
329					i_wb_shifted[DATA_WIDTH-1:INSN_WIDTH] };
330			// Verilator lint_on  UNUSED
331			// }}}
332	`ifdef	FORMAL
333			assign	f_bus_word = rg_insn << ((r_count-1)* INSN_WIDTH);
334			always @(*)
335			if (!i_reset && r_valid)
336			begin
337				assert(i_clear_cache || i_new_pc || o_valid);
338				assert(r_shift == 0);
339				assert((r_count + o_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)])
340					== ((1<<NSHIFT)-1));
341			end else if (!i_reset && !o_valid && o_wb_cyc && !invalid_bus_cycle)
342			begin
343				assert(r_shift == o_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)]);
344			end
345	`endif
346			// }}}
347		end else begin : NO_SUBSHIFT
348			// {{{
349			assign	r_valid = 1'b0;
350			assign	r_insn  = {(INSN_WIDTH){1'b0}};
351			assign	i_wb_shifted = i_wb_data;
352			// }}}
353		end endgenerate
354	
355		// o_valid
356		// {{{
357		initial	o_valid = 1'b0;
358		always @(posedge i_clk)
359		if (i_reset || i_new_pc || i_clear_cache)
360			o_valid <= 1'b0;
361		else if (o_wb_cyc &&(i_wb_ack || i_wb_err))
362			o_valid <= 1'b1;
363		else if (i_ready)
364			o_valid <= cache_valid || r_valid;
365		// }}}
366	
367		// o_insn
368		// {{{
369		always @(posedge i_clk)
370		if (!o_valid || i_ready)
371		begin
372			if (OPT_LITTLE_ENDIAN)
373			begin
374				if (r_valid)
375					o_insn <= r_insn[INSN_WIDTH-1:0];
376				else if (cache_valid)
377					o_insn <= cache_word[INSN_WIDTH-1:0];
378				else
379					o_insn <= i_wb_shifted[INSN_WIDTH-1:0];
380			end else begin
381				if (r_valid)
382					o_insn <= r_insn[DW-1:DW-INSN_WIDTH];
383				else if (cache_valid)
384					o_insn <= cache_word[DW-1:DW-INSN_WIDTH];
385				else
386					o_insn <= i_wb_shifted[DW-1:DW-INSN_WIDTH];
387			end
388		end
389		// }}}
390	
391		// o_pc
392		// {{{
393		always @(posedge i_clk)
394		if (i_new_pc)
395			o_pc <= i_pc;
396		else if (o_valid && i_ready) // && !i_clear_cache
397		begin
398			o_pc <= 0;
399			o_pc[AW-1:$clog2(INSN_WIDTH/8)]
400				<= o_pc[AW-1:$clog2(INSN_WIDTH/8)] + 1'b1;
401		end
402		// }}}
403	
404		// o_illegal
405		// {{{
406		initial	o_illegal = 1'b0;
407		always @(posedge i_clk)
408		if (i_reset || i_new_pc || i_clear_cache)
409			o_illegal <= 1'b0;
410		else if (!r_valid && (!o_valid || i_ready) && !o_illegal)
411		begin
412			if (cache_valid)
413				o_illegal <= cache_illegal;
414			else if (o_wb_cyc && i_wb_err)
415				o_illegal <= 1'b1;
416		end
417		// }}}
418	
419		// }}}
420		////////////////////////////////////////////////////////////////////////
421		//
422		// Now for the output/cached word
423		// {{{
424		////////////////////////////////////////////////////////////////////////
425		//
426		//
427	
428		// cache_valid
429		// {{{
430		initial	cache_valid = 1'b0;
431		always @(posedge i_clk)
432		if ((i_reset)||(i_new_pc)||(i_clear_cache))
433			cache_valid <= 1'b0;
434		else begin
435			if (o_valid && o_wb_cyc &&(i_wb_ack || i_wb_err))
436				cache_valid <= !i_ready || r_valid;
437			else if (i_ready && !r_valid)
438				cache_valid <= 1'b0;
439		end
440	`ifdef	FORMAL
441		always @(*)
442		if (!i_reset && cache_valid && o_wb_cyc)
443			assert(!i_wb_ack && !i_wb_err);
444	`endif
445		// }}}
446	
447		// cache_word
448		// {{{
449		always @(posedge i_clk)
450		if (i_wb_ack)
451			cache_word <= i_wb_data;
452		// }}}
453	
454		// cache_illegal
455		// {{{
456		initial	cache_illegal = 1'b0;
457		always @(posedge i_clk)
458		if (i_reset || i_clear_cache || i_new_pc)
459			cache_illegal <= 1'b0;
460		// Older logic ...
461		// else if ((o_wb_cyc)&&(i_wb_err)&&(o_valid)&&(!i_ready))
462		//	cache_illegal <= 1'b1;
463		else if (o_wb_cyc && i_wb_err)
464				//  && o_valid && (!i_ready || r_valid))
465			cache_illegal <= 1'b1;
466		// }}}
467	
468		// }}}
469	////////////////////////////////////////////////////////////////////////////////
470	////////////////////////////////////////////////////////////////////////////////
471	////////////////////////////////////////////////////////////////////////////////
472	//
473	// Formal property section
474	// {{{
475	////////////////////////////////////////////////////////////////////////////////
476	////////////////////////////////////////////////////////////////////////////////
477	////////////////////////////////////////////////////////////////////////////////
478	`ifdef	FORMAL
479		// Local declarations
480		// {{{
481		// Keep track of a flag telling us whether or not $past()
482		// will return valid results
483	 	reg	f_past_valid;
484	
485		// Keep track of some alternatives to $past that can still be used
486		// in a VERILATOR environment
487		reg	[AW-1:0]	f_next_addr, f_dbl_next, f_cache_addr; //bytaddr
488		localparam	F_LGDEPTH=2;
489		wire	[(F_LGDEPTH-1):0]	f_nreqs, f_nacks, f_outstanding;
490		wire		[AW-1:0]	f_const_addr;
491		wire		[DW-1:0]	f_const_insn;
492		wire				f_const_illegal;
493		wire	f_this_pc,
494			f_this_insn, f_this_return;
495		wire	[AW-$clog2(DATA_WIDTH/8)-1:0]	this_return_address,
496					f_const_bus_addr, next_pc_address;
497		wire	[AW-1:0]	f_address;
498		(* anyconst *)	wire	[DW-1:0]	f_const_bus_word;
499		reg	[AW-$clog2(DW/8)-1:0]	pc_bus_addr, pc_bus_addr_next,
500						pc_bus_addr_dbl;
501	
502		initial	f_past_valid = 1'b0;
503		always @(posedge i_clk)
504			f_past_valid <= 1'b1;
505		// }}}
506	
507		generate if (INSN_WIDTH == 8)
508		begin : F_NEXT_BYTE_ADDR
509			// {{{
510			// BUS addresses
511			always @(*)
512				f_next_addr = o_pc + (r_valid ? 0:1);
513			// }}}
514		end else begin : F_NEXT_ADDR
515			// {{{
516			// BUS addresses
517			always @(*)
518			if (r_valid)
519				f_next_addr = o_pc;
520			else begin
521				f_next_addr = o_pc + (INSN_WIDTH/8);
522				f_next_addr[$clog2(INSN_WIDTH/8)-1:0] = 0;
523			end
524			// }}}
525		end endgenerate
526	
527		always @(*)
528		begin
529			// BUS addresses
530			f_dbl_next = f_next_addr + (DATA_WIDTH/8);
531			if (r_valid)
532				f_dbl_next = f_dbl_next + (DATA_WIDTH/8);
533			f_dbl_next[$clog2(DATA_WIDTH/8)-1:0] = 0;
534	
535			f_cache_addr = o_pc + (DATA_WIDTH/8);
536			f_cache_addr[$clog2(DATA_WIDTH/8)-1:0] = 0;
537		end
538	
539		////////////////////////////////////////////////////////////////////////
540		//
541		// Assumptions about our inputs
542		// {{{
543		////////////////////////////////////////////////////////////////////////
544		//
545		//
546		//
547	
548		//
549		// Assume that resets, new-pc commands, and clear-cache commands
550		// are never more than pulses--one clock wide at most.
551		//
552		// It may be that the CPU treats us differently.  We'll only restrict
553		// our solver to this here.
554		// }}}
555		////////////////////////////////////////////////////////////////////////
556		//
557		// Wishbone bus properties
558		// {{{
559		////////////////////////////////////////////////////////////////////////
560		//
561		//
562	
563		//
564		// Add a bunch of wishbone-based asserts
565		fwb_master #(
566			// {{{
567			.AW(AW-$clog2(DATA_WIDTH/8)), .DW(DW), .F_LGDEPTH(F_LGDEPTH),
568				.F_MAX_STALL(2),
569				.F_MAX_REQUESTS(0), .F_OPT_SOURCE(1),
570				.F_OPT_RMW_BUS_OPTION(1),
571				.F_OPT_DISCONTINUOUS(0)
572			// }}}
573		) f_wbm(
574			// {{{
575			i_clk, i_reset,
576				o_wb_cyc, o_wb_stb, o_wb_we, o_wb_addr, o_wb_data,
577					{(DW/8){1'b1}},
578				i_wb_ack, i_wb_stall, i_wb_data, i_wb_err,
579				f_nreqs, f_nacks, f_outstanding
580			// }}}
581		);
582		// }}}
583		////////////////////////////////////////////////////////////////////////
584		//
585		// Assumptions about our interaction with the CPU
586		// {{{
587		////////////////////////////////////////////////////////////////////////
588		//
589		//
590	
591		ffetch #(
592			// {{{
593			.ADDRESS_WIDTH(AW-$clog2(INSN_WIDTH/8)),
594			.INSN_WIDTH(INSN_WIDTH)
595			// }}}
596		) cpu(
597			// {{{
598			.i_clk(i_clk), .i_reset(i_reset),
599			.cpu_new_pc(i_new_pc), .cpu_clear_cache(i_clear_cache),
600			.cpu_pc(i_pc), .pf_valid(o_valid), .cpu_ready(i_ready),
601			.pf_pc(o_pc), .pf_insn(o_insn), .pf_illegal(o_illegal),
602			.fc_illegal(f_const_illegal), .fc_insn(f_const_insn),
603			.fc_pc(f_const_addr), .f_address(f_address)
604			// }}}
605		);
606	
607		assign	f_const_bus_addr = f_const_addr[AW-1:$clog2(DATA_WIDTH/8)];
608	
609		//
610		// Let's make some assumptions about how long it takes our phantom
611		// (i.e. assumed) CPU to respond.
612		//
613		// This delay needs to be long enough to flush out any potential
614		// errors, yet still short enough that the formal method doesn't
615		// take forever to solve.
616		//
617		localparam	F_CPU_DELAY = 4;
618		reg	[4:0]	f_cpu_delay;
619	
620		// Now, let's look at the delay the CPU takes to accept an instruction.
621		always @(posedge i_clk)
622		// If no instruction is ready, then keep our counter at zero
623		if ((!o_valid)||(i_ready))
624			f_cpu_delay <= 0;
625		else
626			// Otherwise, count the clocks the CPU takes to respond
627			f_cpu_delay <= f_cpu_delay + 1'b1;
628	
629		always @(posedge i_clk)
630			assume(f_cpu_delay < F_CPU_DELAY);
631		// }}}
632		////////////////////////////////////////////////////////////////////////
633		//
634		// Assertions about our outputs
635		// {{{
636		//
637		////////////////////////////////////////////////////////////////////////
638		//
639		//
640		always @(posedge i_clk)
641		if ((f_past_valid)&&($past(o_wb_stb))&&(!$past(i_wb_stall))
642				&&($past(!i_new_pc && !i_clear_cache)))
643			assert(o_wb_addr <= $past(o_wb_addr)+1'b1);
644	
645		//
646		// The cache doesn't change if we are stalled
647		//
648		always @(posedge i_clk)
649		if ((f_past_valid)&&(!$past(i_reset))
650				&&(!$past(i_new_pc))&&(!$past(i_clear_cache))
651				&&($past(o_valid))&&(!$past(i_ready || r_valid))
652				&&($past(cache_valid)))
653		begin
654			assert($stable(cache_valid));
655			assert($stable(cache_word));
656			assert($stable(cache_illegal));
657		end
658	
659		// Consider it invalid to present the CPU with the same instruction
660		// twice in a row.  Any effort to present the CPU with the same
661		// instruction twice in a row must go through i_new_pc, and thus a
662		// new bus cycle--hence the assertion below makes sense.
663		always @(posedge i_clk)
664		if ((f_past_valid)&& $past(!i_new_pc && !i_clear_cache)
665				&&($past(o_valid && i_ready)))
666			assert(o_pc == f_address);
667	
668		always @(posedge i_clk)
669		if (!i_reset && !i_clear_cache && !i_new_pc)
670			assert(o_pc == f_address);
671	
672	
673		always @(posedge i_clk)
674		if ((f_past_valid)&&(!$past(i_reset))
675				&&(!$past(i_new_pc))
676				&&(!$past(i_clear_cache))
677				&&($past(o_wb_cyc))&&($past(i_wb_err)))
678			assert( ((o_valid)&&(o_illegal))
679				||((cache_valid)&&(cache_illegal)) );
680	
681		always @(posedge i_clk)
682		if ((f_past_valid)&&(!$past(o_illegal))&&(o_illegal))
683			assert(o_valid);
684	
685		always @(posedge i_clk)
686		if (!i_reset && cache_illegal)
687			assert(!o_wb_cyc);
688	
689		always @(posedge i_clk)
690		if ((f_past_valid)&&($past(i_new_pc)))
691			assert(!o_valid);
692	
693		always @(posedge i_clk)
694		if ((f_past_valid)&&(!$past(i_reset))&&(!$past(i_clear_cache))
695				&&($past(o_valid))&&(!o_valid)&&(!o_illegal))
696			assert((o_wb_cyc)||(invalid_bus_cycle));
697		// }}}
698		////////////////////////////////////////////////////////////////////////
699		//
700		//
701		// Our "contract" with the CPU
702		// {{{
703		//
704		////////////////////////////////////////////////////////////////////////
705		//
706		// For any particular address, that address is associated with an
707		// instruction and a flag regarding whether or not it is illegal.
708		//
709		// Any attempt to return to the CPU a value from this address,
710		// must return the value and the illegal flag.
711		//
712	
713		//
714		// While these wires may seem like overkill, and while they make the
715		// following logic perhaps a bit more obscure, these predicates make
716		// it easier to follow the complex logic on a scope.  They don't
717		// affect anything synthesized.
718		//
719		assign	f_this_pc   = (o_pc[AW-1:$clog2(INSN_WIDTH/8)]
720					== f_const_addr[AW-1:$clog2(INSN_WIDTH/8)]);
721		assign	f_this_insn = (o_insn    ==   f_const_insn);
722	
723		// Verilator lint_off WIDTH
724		assign	f_this_return = (o_wb_addr - f_outstanding == f_const_addr[AW-1:$clog2(DATA_WIDTH/8)]);
725		// Verilator lint_on  WIDTH
726	
727	
728		//
729		//
730		// Here's our contract:
731		//
732		// Any time we return a value for the address above, it *must* be
733		// the "right" value.
734		//
735		always @(*)
736		if (o_valid && f_this_pc)
737		begin
738			if (f_const_illegal)
739				assert(o_illegal);
740			if (!o_illegal)
741				assert(f_this_insn);
742		end
743	
744		//
745		// The contract will only work if we assume the return from the
746		// bus at this address will be the right return.
747		always @(*)
748		if ((o_wb_cyc)&&(f_this_return))
749		begin
750			if (i_wb_ack)
751				assume(i_wb_data == f_const_bus_word);
752	
753			if (f_const_illegal)
754			begin
755				assume(!i_wb_ack);
756			end else
757				assume(!i_wb_err);
758		end
759	
760		generate if (INSN_WIDTH == DATA_WIDTH)
761		begin : F_SAME_BUS_WORD
762			// {{{
763			always @(*)
764				assume(f_const_bus_word == f_const_insn);
765			// }}}
766		end else begin : F_CHECK_SHIFTED_WORD
767			// {{{
768			wire	[DW-1:0]	f_shifted_insn;
769			localparam		IW = INSN_WIDTH;
770	
771			if (OPT_LITTLE_ENDIAN)
772			begin
773				assign  f_shifted_insn = f_const_bus_word
774					>> (f_const_addr[$clog2(DW/8)-1:$clog2(IW/8)] * IW);
775				always @(*)
776					assume(f_shifted_insn[IW-1:0] == f_const_insn);
777	
778			end else begin
779				assign  f_shifted_insn = f_const_bus_word
780					<< (f_const_addr[$clog2(DW/8)-1:$clog2(IW/8)] * IW);
781	
782				always @(*)
783					assume(f_shifted_insn[DW-1:DW-IW]
784						== f_const_insn);
785	
786			end
787	                // }}}
788		end endgenerate
789	
790		//
791		// Here is a corrollary to our contract.  Anything in the one-word
792		// cache must also match the contract as well.
793		//
794		always @(*)
795		if ((f_cache_addr[AW-1:$clog2(DATA_WIDTH/8)] == f_const_bus_addr)
796				&&(cache_valid))
797		begin
798			if (!cache_illegal)
799				assert(cache_word == f_const_bus_word);
800	
801			if (f_const_illegal)
802				assert(cache_illegal);
803			else
804				assert(o_illegal || !cache_illegal);
805		end
806	
807		// always @(posedge i_clk)
808		// if ((f_past_valid)&&(!$past(cache_illegal))&&(!cache_valid))
809		//	assert(!cache_illegal);
810		// }}}
811		////////////////////////////////////////////////////////////////////////
812		//
813		// Additional assertions necessary to pass induction
814		// {{{
815		////////////////////////////////////////////////////////////////////////
816		//
817		//
818		// We have only a one word cache.  Hence, we shouldn't be asking
819		// for more data any time we have nowhere to put it.
820		always @(*)
821		if (o_wb_stb)
822			assert(!cache_valid || i_ready);
823	
824		always @(*)
825		if (o_valid && cache_valid)
826			assert((f_outstanding == 0)&&(!o_wb_stb));
827	
828		always @(*)
829		if (o_valid && (r_valid || !i_ready))
830			assert(f_outstanding < 2);
831	
832		always @(*)
833		if (!o_valid || (i_ready && !r_valid))
834			assert(f_outstanding <= 2);
835	
836		// always @(posedge i_clk)
837		// if ((f_past_valid)&&($past(o_wb_cyc && !o_wb_stb)) &&(o_wb_cyc))
838		//	assert(inflight != 0);
839	
840		always @(*)
841		if (o_wb_cyc && i_wb_ack)
842			assert(!cache_valid);
843	
844		always @(posedge i_clk)
845		if (o_wb_cyc)
846			assert(inflight == f_outstanding);
847	
848		// Verilator lint_off WIDTH
849		assign	this_return_address = o_wb_addr - f_outstanding;
850		// Verilator lint_on  WIDTH
851		assign	next_pc_address = f_next_addr[AW-1:$clog2(DATA_WIDTH/8)];
852		// }}}
853		////////////////////////////////////////////////////////////////////////
854		//
855		// Address checking
856		// {{{
857		////////////////////////////////////////////////////////////////////////
858		//
859		//
860	
861		always @(*)
862		begin
863			pc_bus_addr      = o_pc[AW-1:$clog2(DW/8)];
864			pc_bus_addr_next = pc_bus_addr + 1;
865			pc_bus_addr_dbl  = pc_bus_addr + 2;
866		end
867	
868		always @(*)
869		if (i_reset || o_illegal || invalid_bus_cycle)
870		begin
871		end else if (!o_valid)
872		begin
873			if (o_wb_cyc)
874			begin
875				if (inflight == 0)
876					assert(o_wb_addr == pc_bus_addr);
877				assert(pc_bus_addr == this_return_address);
878			end
879		end else if (cache_valid || (o_wb_cyc && !o_wb_stb))
880		begin
881			assert(o_wb_addr == pc_bus_addr_dbl);
882		end else if (o_valid)
883			assert(o_wb_addr == pc_bus_addr_next);
884	
885		always @(posedge i_clk)
886		if (f_past_valid &&($past(!i_reset && !i_new_pc && !i_clear_cache))
887				&&(!$past(invalid_bus_cycle)))
888		begin
889			if (($past(o_wb_cyc && (i_wb_ack || i_wb_err)))
890				&&($past(!o_valid || (i_ready && !r_valid)))
891				&&(!$past(cache_valid)))
892			begin
893				assert(o_pc[AW-1:$clog2(DW/8)] == $past(this_return_address));
894			end else if (cache_valid)
895			begin
896				assert(o_wb_addr == pc_bus_addr_dbl);
897				assert(f_outstanding == 0);
898			end else if (o_valid)
899			begin
900				if (f_outstanding == 0)
901					assert(o_illegal || o_wb_addr == pc_bus_addr_next);
902				else if (f_outstanding == 1)
903					assert(o_illegal || o_wb_addr == pc_bus_addr_dbl);
904				else if (f_outstanding == 2)
905					assert(o_wb_addr == pc_bus_addr_dbl);
906			end else if (o_wb_cyc)
907				assert(o_pc[AW-1:$clog2(DW/8)] == this_return_address);
908		end
909	
910		always @(posedge i_clk)
911		if (!i_reset && o_illegal)
912		begin
913			assert(!o_wb_cyc);
914			assert(cache_illegal);
915		end
916	
917		always @(posedge i_clk)
918		if ((f_past_valid)&&($past(o_wb_cyc && !i_new_pc))&&(!o_valid)
919				&&(o_wb_cyc))
920			assert(o_pc[AW-1:$clog2(DW/8)] == this_return_address);
921	
922		always @(posedge i_clk)
923		if (o_valid && !o_wb_cyc && !o_illegal)
924		begin
925			if (cache_valid)
926				assert(f_dbl_next[AW-1:$clog2(DW/8)] == o_wb_addr);
927			else
928				assert(pc_bus_addr_next == o_wb_addr);
929	
930		end
931	
932		always @(*)
933		if (o_wb_cyc || o_valid)
934		begin
935			assert(o_wb_addr == pc_bus_addr
936				|| o_wb_addr == pc_bus_addr_next
937				|| o_wb_addr == pc_bus_addr_dbl);
938		end
939	
940	//	always @(posedge i_clk)
941	//	if ((f_past_valid)&& $past(o_wb_cyc && !cache_valid) && cache_valid)
942	//		assert(next_pc_address == $past(this_return_address));
943	
944		//
945		//
946	
947		always @(posedge i_clk)
948		if ((f_past_valid)&&($past(o_wb_cyc))&&(o_wb_cyc))
949		begin
950			if (o_valid && !cache_valid)
951			begin
952				// assert(this_return_address == next_pc_address);
953			end else if (!o_valid)
954				assert(this_return_address == o_pc[AW-1:$clog2(DW/8)]);
955		end else if ((f_past_valid)&&(!invalid_bus_cycle)
956				&&(!o_wb_cyc)&&(o_valid)&&(!o_illegal)
957				&&(!cache_valid))
958			assert(o_wb_addr == next_pc_address);
959	
960	
961		always @(*)
962		if (invalid_bus_cycle)
963			assert(!o_wb_cyc);
964	
965		always @(*)
966		if (cache_valid)
967			assert(o_valid);
968		// }}}
969		////////////////////////////////////////////////////////////////////////
970		//
971		// Cover statements
972		// {{{
973		////////////////////////////////////////////////////////////////////////
974		//
975		//
976		reg	f_cvr_aborted, f_cvr_fourth_ack;
977	
978		always @(posedge i_clk)
979		cover((f_past_valid)&&($past(f_nacks)==3)
980			&&($past(i_wb_ack))&&($past(o_wb_cyc)));
981	
982		initial	f_cvr_aborted = 0;
983		always @(posedge i_clk)
984		if (i_reset)
985			f_cvr_aborted <= 0;
986		else if (!o_wb_cyc && (f_nreqs != f_nacks))
987			f_cvr_aborted <= 1;
988	
989		initial	f_cvr_fourth_ack = 0;
990		always @(posedge i_clk)
991		if (i_reset)
992			f_cvr_fourth_ack <= 0;
993		else if ((f_nacks == 3)&&(o_wb_cyc && i_wb_ack))
994			f_cvr_fourth_ack <= 1;
995	
996		always @(posedge i_clk)
997			cover(!o_wb_cyc && (f_nreqs == f_nacks)
998				&& !f_cvr_aborted && f_cvr_fourth_ack);
999		// }}}
1000		////////////////////////////////////////////////////////////////////////
1001		//
1002		// Temporary simplifications
1003		// {{{
1004		////////////////////////////////////////////////////////////////////////
1005		//
1006		//
1007	
1008		// }}}
1009	
1010		// Make Verilator happy -- formal section
1011		// {{{
1012		// Verilator lint_off UNUSED
1013		wire	unused_formal;
1014		assign	unused_formal = &{ f_dbl_next[1:0], f_const_addr[1:0] };
1015		// Verilator lint_on  UNUSED
1016		// }}}
1017	`endif	// FORMAL
1018	// }}}
1019	endmodule
1020	//
1021	// Usage:		(this)	(prior)	(old)  (S6)
1022	//    Cells		374	387	585	459
1023	//	FDRE		135	108	203	171
1024	//	LUT1		  2	  3	  2
1025	//	LUT2		  9	  3	  4	  5
1026	//	LUT3		 98	 76	104	 71
1027	//	LUT4		  2	  0	  2	  2
1028	//	LUT5		  3	 35	 35	  3
1029	//	LUT6		  6	  5	 10	 43
1030	//	MUXCY		 58	 62	 93	 62
1031	//	MUXF7		  1	  0	  2	  3
1032	//	MUXF8		  0	  1	  1
1033	//	RAM64X1D	  0	 32	 32	 32
1034	//	XORCY		 60	 64	 96	 64
1035	//
