////////////////////////////////////////////////////////////////////////////////
//
// Filename:	rtl/core/dblfetch.v
// {{{
// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
//
// Purpose:	This is one step beyond the simplest instruction fetch,
//		prefetch.v.  dblfetch.v uses memory pipelining to fetch two
//	(or more) instruction words in one bus cycle.  If the CPU consumes
//	either of these before the bus cycle completes, a new request will be
//	made of the bus.  In this way, we can keep the CPU filled in spite
//	of a (potentially) slow memory operation.  The bus request will end
//	when both requests have been sent and both result locations are empty.
//
//	This routine is designed to be a touch faster than the single
//	instruction prefetch (prefetch.v), although not as fast as the
//	prefetch and cache approach found elsewhere (pfcache.v).
//
//	20180222: Completely rebuilt.
//
// Creator:	Dan Gisselquist, Ph.D.
//		Gisselquist Technology, LLC
//
////////////////////////////////////////////////////////////////////////////////
// }}}
// Copyright (C) 2017-2025, Gisselquist Technology, LLC
// {{{
// This program is free software (firmware): you can redistribute it and/or
// modify it under the terms of the GNU General Public License as published
// by the Free Software Foundation, either version 3 of the License, or (at
// your option) any later version.
//
// This program is distributed in the hope that it will be useful, but WITHOUT
// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
// for more details.
//
// You should have received a copy of the GNU General Public License along
// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
// target there if the PDF file isn't present.)  If not, see
// <http://www.gnu.org/licenses/> for a copy.
// }}}
// License:	GPL, v3, as defined and found on www.gnu.org,
// {{{
//		http://www.gnu.org/licenses/gpl.html
//
////////////////////////////////////////////////////////////////////////////////
//
`default_nettype	none
// }}}
module	dblfetch #(
		// {{{
		parameter		ADDRESS_WIDTH=30,	// Byte addr
		parameter		INSN_WIDTH=32,
		parameter		DATA_WIDTH = INSN_WIDTH,
		localparam		AW=ADDRESS_WIDTH,
					DW=DATA_WIDTH,
		parameter	[0:0]	OPT_LITTLE_ENDIAN = 1'b1
		// }}}
	) (
		// {{{
		input	wire			i_clk, i_reset,
		// CPU signals--from the CPU
		input	wire			i_new_pc, i_clear_cache,i_ready,
		input	wire	[AW-1:0]	i_pc,
		// ... and in return
		output	reg			o_valid,
		output	reg			o_illegal,
		output	reg [INSN_WIDTH-1:0]	o_insn,
		output	reg	[AW-1:0]	o_pc,
		// Wishbone outputs
		output	reg			o_wb_cyc, o_wb_stb,
		// verilator coverage_off
		output	wire			o_wb_we,
		// verilator coverage_on
		output	reg [AW-$clog2(DW/8)-1:0] o_wb_addr,
		// verilator coverage_off
		output	wire	[DW-1:0]	o_wb_data,
		// verilator coverage_on
		// And return inputs
		input	wire			i_wb_stall, i_wb_ack, i_wb_err,
		input	wire	[DW-1:0]	i_wb_data
		// }}}
	);

	// Local declarations
	// {{{
	wire			last_stb;
	reg			invalid_bus_cycle;

	reg	[(DW-1):0]	cache_word;
	reg			cache_valid;
	reg	[1:0]		inflight;
	reg			cache_illegal;

	wire				r_valid;
	wire	[DATA_WIDTH-1:0]	r_insn, i_wb_shifted;
	// }}}

	assign	o_wb_we = 1'b0;
	assign	o_wb_data = {(DATA_WIDTH){1'b0}};

	// o_wb_cyc, o_wb_stb
	// {{{
	initial	o_wb_cyc = 1'b0;
	initial	o_wb_stb = 1'b0;
	always @(posedge i_clk)
	if (i_reset || i_clear_cache || (o_wb_cyc && i_wb_err))
	begin : RESET_ABORT
		// {{{
		o_wb_cyc <= 1'b0;
		o_wb_stb <= 1'b0;
		// }}}
	end else if (o_wb_cyc)
	begin : END_CYCLE
		// {{{
		if (!o_wb_stb || !i_wb_stall)
			o_wb_stb <= (!last_stb);

		// Relase the bus on the second ack
		if ((!o_wb_stb || !i_wb_stall) && last_stb
			&& inflight + (o_wb_stb ? 1:0) == (i_wb_ack ? 1:0))
		begin
			o_wb_cyc <= 1'b0;
			o_wb_stb <= 1'b0;
		end

		if (i_new_pc) // || i_clear_cache)
			{ o_wb_cyc, o_wb_stb } <= 2'b0;
		// }}}
	end else if ((i_new_pc || invalid_bus_cycle)
		||(o_valid && i_ready && !r_valid && !cache_illegal))
	begin : START_CYCLE
		// {{{
		// Initiate a bus cycle if ... the last bus cycle was
		// aborted (bus error or new_pc), we've been given a
		// new PC to go get, or we just exhausted our one
		// instruction cache
		o_wb_cyc <= 1'b1;
		o_wb_stb <= 1'b1;
		// }}}
	end
	// }}}

	// inflight
	// {{{
	initial	inflight = 2'b00;
	always @(posedge i_clk)
	if (!o_wb_cyc)
		inflight <= 2'b00;
	else begin
		case({ (o_wb_stb && !i_wb_stall), i_wb_ack })
		2'b01:	inflight <= inflight - 1'b1;
		2'b10:	inflight <= inflight + 1'b1;
		// If neither ack nor request, then no change.  Likewise
		// if we have both an ack and a request, there's no change
		// in the number of requests in flight.
		default: begin end
		endcase
	end
	// }}}

	// last_stb
	// {{{
	// assign last_stb = (inflight != 2'b00)||(o_valid&& (!i_ready||r_valid));
	assign	last_stb = (!o_wb_stb||!i_wb_stall)&&(inflight
		+ (o_wb_stb ? 1:0)
		+ (o_valid&&(!i_ready || r_valid)) >= 2'b10);
	// }}}

	// invalid_bus_cycle
	// {{{
	initial	invalid_bus_cycle = 1'b0;
	always @(posedge i_clk)
	if (i_reset)
		invalid_bus_cycle <= 1'b0;
	else if (o_wb_cyc && i_new_pc)
		invalid_bus_cycle <= 1'b1;
	else if (!o_wb_cyc)
		invalid_bus_cycle <= 1'b0;
	// }}}

	// o_wb_addr
	// {{{
	initial	o_wb_addr = {(AW-$clog2(DATA_WIDTH/8)){1'b1}};
	always @(posedge i_clk)
	if (i_new_pc)
		o_wb_addr <= i_pc[AW-1:$clog2(DATA_WIDTH/8)];
	// else if (i_clear_cache)
	//	o_wb_addr <= o_pc[AW-1:$clog2(DATA_WIDTH/8)];
	else if (o_wb_stb && !i_wb_stall)
		o_wb_addr <= o_wb_addr + 1'b1;
	// }}}

	////////////////////////////////////////////////////////////////////////
	//
	// Now for the immediate output word to the CPU
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	// This only applies when the bus size doesn't match the instruction
	// word size.  Here, we only support bus sizes greater than the
	// instruction word size.
`ifdef	FORMAL
	wire	[DATA_WIDTH-1:0]	f_bus_word;
`endif

	generate if (DATA_WIDTH > INSN_WIDTH)
	begin : GEN_SUBSHIFT
		// {{{
		localparam	NSHIFT = $clog2(DATA_WIDTH/INSN_WIDTH);

		reg			rg_valid;
		reg [DATA_WIDTH-1:0]	rg_insn;
		reg	[NSHIFT:0]	r_count;
		reg	[NSHIFT-1:0]	r_shift;

		// rg_valid
		// {{{
		always @(posedge i_clk)
		if (i_reset || i_new_pc) // || i_clear_cache)
			rg_valid <= 1'b0;
		else if (r_valid)
			rg_valid <= !i_ready || (r_count > 1);
		else if (!o_valid || i_ready)
		begin
			rg_valid <= 1'b0;
			if (cache_valid)
				rg_valid <= 1'b1;
			if (o_wb_cyc && i_wb_ack && !(&r_shift))
				rg_valid <= 1'b1;
		end
		// }}}

		// rg_insn
		// {{{
		always @(posedge i_clk)
		if (!o_valid || i_ready)
		begin
			if (cache_valid && !r_valid)
			begin
				if (OPT_LITTLE_ENDIAN)
					rg_insn <= cache_word >> INSN_WIDTH;
				else
					rg_insn <= cache_word << INSN_WIDTH;
			end else if (i_wb_ack && !r_valid)
			begin
				rg_insn <= i_wb_data;
				if (OPT_LITTLE_ENDIAN)
					rg_insn <= i_wb_shifted >> INSN_WIDTH;
				else
					rg_insn <= i_wb_shifted << INSN_WIDTH;
			end else begin
				if (OPT_LITTLE_ENDIAN)
					rg_insn <= rg_insn >> INSN_WIDTH;
				else
					rg_insn <= rg_insn << INSN_WIDTH;
			end
		end
		// }}}

		// r_count
		// {{{
		always @(posedge i_clk)
		if (i_reset || i_new_pc) // || i_clear_cache)
			r_count <= 0;
		else if (o_valid && i_ready && r_valid)
		begin
			r_count <= r_count - 1;
		end else if (!o_valid || (i_ready && !r_valid))
		begin
			if (cache_valid)
				r_count <= { 1'b0, {(NSHIFT){1'b1}} };
			else if (o_wb_cyc && i_wb_ack)
				r_count <= { 1'b0, ~r_shift };
		end
`ifdef	FORMAL
		always @(*)
		if (!i_reset && !i_new_pc && !i_clear_cache)
		begin
			if (!o_valid)
				assert(!r_valid);
			assert(r_valid == (r_count > 0));
			assert(r_count <= (1<<NSHIFT));
			if (r_valid)
			begin
				assert(!cache_valid || !o_wb_cyc);
				assert(r_shift == 0);
			end else if (!i_new_pc && !i_clear_cache && !o_illegal)
				assert(invalid_bus_cycle || o_valid || o_wb_cyc);
		end
`endif
		// }}}

		// r_shift
		// {{{
		always @(posedge i_clk)
		if (i_new_pc)
			r_shift <= i_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)];
		// else if (i_clear_cache)
		//	r_shift <= o_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)];
		else if (o_wb_cyc && (i_wb_ack || i_wb_err))
			r_shift <= 0;

`ifdef	FORMAL
		always @(*)
		if (!i_reset && r_shift > 0)
			assert(!o_valid && !r_valid);
`endif
		// }}}

		assign	r_valid = rg_valid;
		assign	r_insn  = rg_insn;
		if (OPT_LITTLE_ENDIAN)
		begin : GEN_LITTLE_ENDIAN_SHIFT
			assign	i_wb_shifted = i_wb_data >> (r_shift * INSN_WIDTH);
		end else begin : GEN_BIGENDIAN_SHIFT
			assign	i_wb_shifted = i_wb_data << (r_shift * INSN_WIDTH);
		end

		// Keep Verilator happy
		// {{{
		// Verilator lint_off UNUSED
		wire	unused_shift;
		assign	unused_shift = &{ 1'b0,
				r_insn[DATA_WIDTH-1:INSN_WIDTH],
				i_wb_shifted[DATA_WIDTH-1:INSN_WIDTH] };
		// Verilator lint_on  UNUSED
		// }}}
`ifdef	FORMAL
		assign	f_bus_word = rg_insn << ((r_count-1)* INSN_WIDTH);
		always @(*)
		if (!i_reset && r_valid)
		begin
			assert(i_clear_cache || i_new_pc || o_valid);
			assert(r_shift == 0);
			assert((r_count + o_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)])
				== ((1<<NSHIFT)-1));
		end else if (!i_reset && !o_valid && o_wb_cyc && !invalid_bus_cycle)
		begin
			assert(r_shift == o_pc[$clog2(DW/8)-1:$clog2(INSN_WIDTH/8)]);
		end
`endif
		// }}}
	end else begin : NO_SUBSHIFT
		// {{{
		assign	r_valid = 1'b0;
		assign	r_insn  = {(INSN_WIDTH){1'b0}};
		assign	i_wb_shifted = i_wb_data;
		// }}}
	end endgenerate

	// o_valid
	// {{{
	initial	o_valid = 1'b0;
	always @(posedge i_clk)
	if (i_reset || i_new_pc || i_clear_cache)
		o_valid <= 1'b0;
	else if (o_wb_cyc &&(i_wb_ack || i_wb_err))
		o_valid <= 1'b1;
	else if (i_ready)
		o_valid <= cache_valid || r_valid;
	// }}}

	// o_insn
	// {{{
	always @(posedge i_clk)
	if (!o_valid || i_ready)
	begin
		if (OPT_LITTLE_ENDIAN)
		begin
			if (r_valid)
				o_insn <= r_insn[INSN_WIDTH-1:0];
			else if (cache_valid)
				o_insn <= cache_word[INSN_WIDTH-1:0];
			else
				o_insn <= i_wb_shifted[INSN_WIDTH-1:0];
		end else begin
			if (r_valid)
				o_insn <= r_insn[DW-1:DW-INSN_WIDTH];
			else if (cache_valid)
				o_insn <= cache_word[DW-1:DW-INSN_WIDTH];
			else
				o_insn <= i_wb_shifted[DW-1:DW-INSN_WIDTH];
		end
	end
	// }}}

	// o_pc
	// {{{
	always @(posedge i_clk)
	if (i_new_pc)
		o_pc <= i_pc;
	else if (o_valid && i_ready) // && !i_clear_cache
	begin
		o_pc <= 0;
		o_pc[AW-1:$clog2(INSN_WIDTH/8)]
			<= o_pc[AW-1:$clog2(INSN_WIDTH/8)] + 1'b1;
	end
	// }}}

	// o_illegal
	// {{{
	initial	o_illegal = 1'b0;
	always @(posedge i_clk)
	if (i_reset || i_new_pc || i_clear_cache)
		o_illegal <= 1'b0;
	else if (!r_valid && (!o_valid || i_ready) && !o_illegal)
	begin
		if (cache_valid)
			o_illegal <= cache_illegal;
		else if (o_wb_cyc && i_wb_err)
			o_illegal <= 1'b1;
	end
	// }}}

	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Now for the output/cached word
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	// cache_valid
	// {{{
	initial	cache_valid = 1'b0;
	always @(posedge i_clk)
	if ((i_reset)||(i_new_pc)||(i_clear_cache))
		cache_valid <= 1'b0;
	else begin
		if (o_valid && o_wb_cyc &&(i_wb_ack || i_wb_err))
			cache_valid <= !i_ready || r_valid;
		else if (i_ready && !r_valid)
			cache_valid <= 1'b0;
	end
`ifdef	FORMAL
	always @(*)
	if (!i_reset && cache_valid && o_wb_cyc)
		assert(!i_wb_ack && !i_wb_err);
`endif
	// }}}

	// cache_word
	// {{{
	always @(posedge i_clk)
	if (i_wb_ack)
		cache_word <= i_wb_data;
	// }}}

	// cache_illegal
	// {{{
	initial	cache_illegal = 1'b0;
	always @(posedge i_clk)
	if (i_reset || i_clear_cache || i_new_pc)
		cache_illegal <= 1'b0;
	// Older logic ...
	// else if ((o_wb_cyc)&&(i_wb_err)&&(o_valid)&&(!i_ready))
	//	cache_illegal <= 1'b1;
	else if (o_wb_cyc && i_wb_err)
			//  && o_valid && (!i_ready || r_valid))
		cache_illegal <= 1'b1;
	// }}}

	// }}}
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
//
// Formal property section
// {{{
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
////////////////////////////////////////////////////////////////////////////////
`ifdef	FORMAL
	// Local declarations
	// {{{
	// Keep track of a flag telling us whether or not $past()
	// will return valid results
 	reg	f_past_valid;

	// Keep track of some alternatives to $past that can still be used
	// in a VERILATOR environment
	reg	[AW-1:0]	f_next_addr, f_dbl_next, f_cache_addr; //bytaddr
	localparam	F_LGDEPTH=2;
	wire	[(F_LGDEPTH-1):0]	f_nreqs, f_nacks, f_outstanding;
	wire		[AW-1:0]	f_const_addr;
	wire		[DW-1:0]	f_const_insn;
	wire				f_const_illegal;
	wire	f_this_pc,
		f_this_insn, f_this_return;
	wire	[AW-$clog2(DATA_WIDTH/8)-1:0]	this_return_address,
				f_const_bus_addr, next_pc_address;
	wire	[AW-1:0]	f_address;
	(* anyconst *)	wire	[DW-1:0]	f_const_bus_word;
	reg	[AW-$clog2(DW/8)-1:0]	pc_bus_addr, pc_bus_addr_next,
					pc_bus_addr_dbl;

	initial	f_past_valid = 1'b0;
	always @(posedge i_clk)
		f_past_valid <= 1'b1;
	// }}}

	generate if (INSN_WIDTH == 8)
	begin : F_NEXT_BYTE_ADDR
		// {{{
		// BUS addresses
		always @(*)
			f_next_addr = o_pc + (r_valid ? 0:1);
		// }}}
	end else begin : F_NEXT_ADDR
		// {{{
		// BUS addresses
		always @(*)
		if (r_valid)
			f_next_addr = o_pc;
		else begin
			f_next_addr = o_pc + (INSN_WIDTH/8);
			f_next_addr[$clog2(INSN_WIDTH/8)-1:0] = 0;
		end
		// }}}
	end endgenerate

	always @(*)
	begin
		// BUS addresses
		f_dbl_next = f_next_addr + (DATA_WIDTH/8);
		if (r_valid)
			f_dbl_next = f_dbl_next + (DATA_WIDTH/8);
		f_dbl_next[$clog2(DATA_WIDTH/8)-1:0] = 0;

		f_cache_addr = o_pc + (DATA_WIDTH/8);
		f_cache_addr[$clog2(DATA_WIDTH/8)-1:0] = 0;
	end

	////////////////////////////////////////////////////////////////////////
	//
	// Assumptions about our inputs
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	//

	//
	// Assume that resets, new-pc commands, and clear-cache commands
	// are never more than pulses--one clock wide at most.
	//
	// It may be that the CPU treats us differently.  We'll only restrict
	// our solver to this here.
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Wishbone bus properties
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	//
	// Add a bunch of wishbone-based asserts
	fwb_master #(
		// {{{
		.AW(AW-$clog2(DATA_WIDTH/8)), .DW(DW), .F_LGDEPTH(F_LGDEPTH),
			.F_MAX_STALL(2),
			.F_MAX_REQUESTS(0), .F_OPT_SOURCE(1),
			.F_OPT_RMW_BUS_OPTION(1),
			.F_OPT_DISCONTINUOUS(0)
		// }}}
	) f_wbm(
		// {{{
		i_clk, i_reset,
			o_wb_cyc, o_wb_stb, o_wb_we, o_wb_addr, o_wb_data,
				{(DW/8){1'b1}},
			i_wb_ack, i_wb_stall, i_wb_data, i_wb_err,
			f_nreqs, f_nacks, f_outstanding
		// }}}
	);
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Assumptions about our interaction with the CPU
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	ffetch #(
		// {{{
		.ADDRESS_WIDTH(AW-$clog2(INSN_WIDTH/8)),
		.INSN_WIDTH(INSN_WIDTH)
		// }}}
	) cpu(
		// {{{
		.i_clk(i_clk), .i_reset(i_reset),
		.cpu_new_pc(i_new_pc), .cpu_clear_cache(i_clear_cache),
		.cpu_pc(i_pc), .pf_valid(o_valid), .cpu_ready(i_ready),
		.pf_pc(o_pc), .pf_insn(o_insn), .pf_illegal(o_illegal),
		.fc_illegal(f_const_illegal), .fc_insn(f_const_insn),
		.fc_pc(f_const_addr), .f_address(f_address)
		// }}}
	);

	assign	f_const_bus_addr = f_const_addr[AW-1:$clog2(DATA_WIDTH/8)];

	//
	// Let's make some assumptions about how long it takes our phantom
	// (i.e. assumed) CPU to respond.
	//
	// This delay needs to be long enough to flush out any potential
	// errors, yet still short enough that the formal method doesn't
	// take forever to solve.
	//
	localparam	F_CPU_DELAY = 4;
	reg	[4:0]	f_cpu_delay;

	// Now, let's look at the delay the CPU takes to accept an instruction.
	always @(posedge i_clk)
	// If no instruction is ready, then keep our counter at zero
	if ((!o_valid)||(i_ready))
		f_cpu_delay <= 0;
	else
		// Otherwise, count the clocks the CPU takes to respond
		f_cpu_delay <= f_cpu_delay + 1'b1;

	always @(posedge i_clk)
		assume(f_cpu_delay < F_CPU_DELAY);
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Assertions about our outputs
	// {{{
	//
	////////////////////////////////////////////////////////////////////////
	//
	//
	always @(posedge i_clk)
	if ((f_past_valid)&&($past(o_wb_stb))&&(!$past(i_wb_stall))
			&&($past(!i_new_pc && !i_clear_cache)))
		assert(o_wb_addr <= $past(o_wb_addr)+1'b1);

	//
	// The cache doesn't change if we are stalled
	//
	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))
			&&(!$past(i_new_pc))&&(!$past(i_clear_cache))
			&&($past(o_valid))&&(!$past(i_ready || r_valid))
			&&($past(cache_valid)))
	begin
		assert($stable(cache_valid));
		assert($stable(cache_word));
		assert($stable(cache_illegal));
	end

	// Consider it invalid to present the CPU with the same instruction
	// twice in a row.  Any effort to present the CPU with the same
	// instruction twice in a row must go through i_new_pc, and thus a
	// new bus cycle--hence the assertion below makes sense.
	always @(posedge i_clk)
	if ((f_past_valid)&& $past(!i_new_pc && !i_clear_cache)
			&&($past(o_valid && i_ready)))
		assert(o_pc == f_address);

	always @(posedge i_clk)
	if (!i_reset && !i_clear_cache && !i_new_pc)
		assert(o_pc == f_address);


	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))
			&&(!$past(i_new_pc))
			&&(!$past(i_clear_cache))
			&&($past(o_wb_cyc))&&($past(i_wb_err)))
		assert( ((o_valid)&&(o_illegal))
			||((cache_valid)&&(cache_illegal)) );

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(o_illegal))&&(o_illegal))
		assert(o_valid);

	always @(posedge i_clk)
	if (!i_reset && cache_illegal)
		assert(!o_wb_cyc);

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(i_new_pc)))
		assert(!o_valid);

	always @(posedge i_clk)
	if ((f_past_valid)&&(!$past(i_reset))&&(!$past(i_clear_cache))
			&&($past(o_valid))&&(!o_valid)&&(!o_illegal))
		assert((o_wb_cyc)||(invalid_bus_cycle));
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	//
	// Our "contract" with the CPU
	// {{{
	//
	////////////////////////////////////////////////////////////////////////
	//
	// For any particular address, that address is associated with an
	// instruction and a flag regarding whether or not it is illegal.
	//
	// Any attempt to return to the CPU a value from this address,
	// must return the value and the illegal flag.
	//

	//
	// While these wires may seem like overkill, and while they make the
	// following logic perhaps a bit more obscure, these predicates make
	// it easier to follow the complex logic on a scope.  They don't
	// affect anything synthesized.
	//
	assign	f_this_pc   = (o_pc[AW-1:$clog2(INSN_WIDTH/8)]
				== f_const_addr[AW-1:$clog2(INSN_WIDTH/8)]);
	assign	f_this_insn = (o_insn    ==   f_const_insn);

	// Verilator lint_off WIDTH
	assign	f_this_return = (o_wb_addr - f_outstanding == f_const_addr[AW-1:$clog2(DATA_WIDTH/8)]);
	// Verilator lint_on  WIDTH


	//
	//
	// Here's our contract:
	//
	// Any time we return a value for the address above, it *must* be
	// the "right" value.
	//
	always @(*)
	if (o_valid && f_this_pc)
	begin
		if (f_const_illegal)
			assert(o_illegal);
		if (!o_illegal)
			assert(f_this_insn);
	end

	//
	// The contract will only work if we assume the return from the
	// bus at this address will be the right return.
	always @(*)
	if ((o_wb_cyc)&&(f_this_return))
	begin
		if (i_wb_ack)
			assume(i_wb_data == f_const_bus_word);

		if (f_const_illegal)
		begin
			assume(!i_wb_ack);
		end else
			assume(!i_wb_err);
	end

	generate if (INSN_WIDTH == DATA_WIDTH)
	begin : F_SAME_BUS_WORD
		// {{{
		always @(*)
			assume(f_const_bus_word == f_const_insn);
		// }}}
	end else begin : F_CHECK_SHIFTED_WORD
		// {{{
		wire	[DW-1:0]	f_shifted_insn;
		localparam		IW = INSN_WIDTH;

		if (OPT_LITTLE_ENDIAN)
		begin
			assign  f_shifted_insn = f_const_bus_word
				>> (f_const_addr[$clog2(DW/8)-1:$clog2(IW/8)] * IW);
			always @(*)
				assume(f_shifted_insn[IW-1:0] == f_const_insn);

		end else begin
			assign  f_shifted_insn = f_const_bus_word
				<< (f_const_addr[$clog2(DW/8)-1:$clog2(IW/8)] * IW);

			always @(*)
				assume(f_shifted_insn[DW-1:DW-IW]
					== f_const_insn);

		end
                // }}}
	end endgenerate

	//
	// Here is a corrollary to our contract.  Anything in the one-word
	// cache must also match the contract as well.
	//
	always @(*)
	if ((f_cache_addr[AW-1:$clog2(DATA_WIDTH/8)] == f_const_bus_addr)
			&&(cache_valid))
	begin
		if (!cache_illegal)
			assert(cache_word == f_const_bus_word);

		if (f_const_illegal)
			assert(cache_illegal);
		else
			assert(o_illegal || !cache_illegal);
	end

	// always @(posedge i_clk)
	// if ((f_past_valid)&&(!$past(cache_illegal))&&(!cache_valid))
	//	assert(!cache_illegal);
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Additional assertions necessary to pass induction
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	// We have only a one word cache.  Hence, we shouldn't be asking
	// for more data any time we have nowhere to put it.
	always @(*)
	if (o_wb_stb)
		assert(!cache_valid || i_ready);

	always @(*)
	if (o_valid && cache_valid)
		assert((f_outstanding == 0)&&(!o_wb_stb));

	always @(*)
	if (o_valid && (r_valid || !i_ready))
		assert(f_outstanding < 2);

	always @(*)
	if (!o_valid || (i_ready && !r_valid))
		assert(f_outstanding <= 2);

	// always @(posedge i_clk)
	// if ((f_past_valid)&&($past(o_wb_cyc && !o_wb_stb)) &&(o_wb_cyc))
	//	assert(inflight != 0);

	always @(*)
	if (o_wb_cyc && i_wb_ack)
		assert(!cache_valid);

	always @(posedge i_clk)
	if (o_wb_cyc)
		assert(inflight == f_outstanding);

	// Verilator lint_off WIDTH
	assign	this_return_address = o_wb_addr - f_outstanding;
	// Verilator lint_on  WIDTH
	assign	next_pc_address = f_next_addr[AW-1:$clog2(DATA_WIDTH/8)];
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Address checking
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	always @(*)
	begin
		pc_bus_addr      = o_pc[AW-1:$clog2(DW/8)];
		pc_bus_addr_next = pc_bus_addr + 1;
		pc_bus_addr_dbl  = pc_bus_addr + 2;
	end

	always @(*)
	if (i_reset || o_illegal || invalid_bus_cycle)
	begin
	end else if (!o_valid)
	begin
		if (o_wb_cyc)
		begin
			if (inflight == 0)
				assert(o_wb_addr == pc_bus_addr);
			assert(pc_bus_addr == this_return_address);
		end
	end else if (cache_valid || (o_wb_cyc && !o_wb_stb))
	begin
		assert(o_wb_addr == pc_bus_addr_dbl);
	end else if (o_valid)
		assert(o_wb_addr == pc_bus_addr_next);

	always @(posedge i_clk)
	if (f_past_valid &&($past(!i_reset && !i_new_pc && !i_clear_cache))
			&&(!$past(invalid_bus_cycle)))
	begin
		if (($past(o_wb_cyc && (i_wb_ack || i_wb_err)))
			&&($past(!o_valid || (i_ready && !r_valid)))
			&&(!$past(cache_valid)))
		begin
			assert(o_pc[AW-1:$clog2(DW/8)] == $past(this_return_address));
		end else if (cache_valid)
		begin
			assert(o_wb_addr == pc_bus_addr_dbl);
			assert(f_outstanding == 0);
		end else if (o_valid)
		begin
			if (f_outstanding == 0)
				assert(o_illegal || o_wb_addr == pc_bus_addr_next);
			else if (f_outstanding == 1)
				assert(o_illegal || o_wb_addr == pc_bus_addr_dbl);
			else if (f_outstanding == 2)
				assert(o_wb_addr == pc_bus_addr_dbl);
		end else if (o_wb_cyc)
			assert(o_pc[AW-1:$clog2(DW/8)] == this_return_address);
	end

	always @(posedge i_clk)
	if (!i_reset && o_illegal)
	begin
		assert(!o_wb_cyc);
		assert(cache_illegal);
	end

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(o_wb_cyc && !i_new_pc))&&(!o_valid)
			&&(o_wb_cyc))
		assert(o_pc[AW-1:$clog2(DW/8)] == this_return_address);

	always @(posedge i_clk)
	if (o_valid && !o_wb_cyc && !o_illegal)
	begin
		if (cache_valid)
			assert(f_dbl_next[AW-1:$clog2(DW/8)] == o_wb_addr);
		else
			assert(pc_bus_addr_next == o_wb_addr);

	end

	always @(*)
	if (o_wb_cyc || o_valid)
	begin
		assert(o_wb_addr == pc_bus_addr
			|| o_wb_addr == pc_bus_addr_next
			|| o_wb_addr == pc_bus_addr_dbl);
	end

//	always @(posedge i_clk)
//	if ((f_past_valid)&& $past(o_wb_cyc && !cache_valid) && cache_valid)
//		assert(next_pc_address == $past(this_return_address));

	//
	//

	always @(posedge i_clk)
	if ((f_past_valid)&&($past(o_wb_cyc))&&(o_wb_cyc))
	begin
		if (o_valid && !cache_valid)
		begin
			// assert(this_return_address == next_pc_address);
		end else if (!o_valid)
			assert(this_return_address == o_pc[AW-1:$clog2(DW/8)]);
	end else if ((f_past_valid)&&(!invalid_bus_cycle)
			&&(!o_wb_cyc)&&(o_valid)&&(!o_illegal)
			&&(!cache_valid))
		assert(o_wb_addr == next_pc_address);


	always @(*)
	if (invalid_bus_cycle)
		assert(!o_wb_cyc);

	always @(*)
	if (cache_valid)
		assert(o_valid);
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Cover statements
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//
	reg	f_cvr_aborted, f_cvr_fourth_ack;

	always @(posedge i_clk)
	cover((f_past_valid)&&($past(f_nacks)==3)
		&&($past(i_wb_ack))&&($past(o_wb_cyc)));

	initial	f_cvr_aborted = 0;
	always @(posedge i_clk)
	if (i_reset)
		f_cvr_aborted <= 0;
	else if (!o_wb_cyc && (f_nreqs != f_nacks))
		f_cvr_aborted <= 1;

	initial	f_cvr_fourth_ack = 0;
	always @(posedge i_clk)
	if (i_reset)
		f_cvr_fourth_ack <= 0;
	else if ((f_nacks == 3)&&(o_wb_cyc && i_wb_ack))
		f_cvr_fourth_ack <= 1;

	always @(posedge i_clk)
		cover(!o_wb_cyc && (f_nreqs == f_nacks)
			&& !f_cvr_aborted && f_cvr_fourth_ack);
	// }}}
	////////////////////////////////////////////////////////////////////////
	//
	// Temporary simplifications
	// {{{
	////////////////////////////////////////////////////////////////////////
	//
	//

	// }}}

	// Make Verilator happy -- formal section
	// {{{
	// Verilator lint_off UNUSED
	wire	unused_formal;
	assign	unused_formal = &{ f_dbl_next[1:0], f_const_addr[1:0] };
	// Verilator lint_on  UNUSED
	// }}}
`endif	// FORMAL
// }}}
endmodule
//
// Usage:		(this)	(prior)	(old)  (S6)
//    Cells		374	387	585	459
//	FDRE		135	108	203	171
//	LUT1		  2	  3	  2
//	LUT2		  9	  3	  4	  5
//	LUT3		 98	 76	104	 71
//	LUT4		  2	  0	  2	  2
//	LUT5		  3	 35	 35	  3
//	LUT6		  6	  5	 10	 43
//	MUXCY		 58	 62	 93	 62
//	MUXF7		  1	  0	  2	  3
//	MUXF8		  0	  1	  1
//	RAM64X1D	  0	 32	 32	 32
//	XORCY		 60	 64	 96	 64
//

content.content:
1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/pffifo.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	This is a basic prefetch.  As with the other prefetches, its job
8	//		is to keep the CPU fed with instructions, (ideally) at one
9	//	instruction per clock cycle and with only a minimum number stalls.
10	//
11	//	This particular implementation is designed around a basic FIFO
12	//	implementation, like the dblfetch implementation, save that we allow a
13	//	FIFO that can hold more than two instructions at a time.  It will work
14	//	well for a CPU that doesn't do a lot of branching, but poorly under
15	//	a high branching load.
16	//
17	// Creator:	Dan Gisselquist, Ph.D.
18	//		Gisselquist Technology, LLC
19	//
20	////////////////////////////////////////////////////////////////////////////////
21	// }}}
22	// Copyright (C) 2015-2025, Gisselquist Technology, LLC
23	// {{{
24	// This program is free software (firmware): you can redistribute it and/or
25	// modify it under the terms of the GNU General Public License as published
26	// by the Free Software Foundation, either version 3 of the License, or (at
27	// your option) any later version.
28	//
29	// This program is distributed in the hope that it will be useful, but WITHOUT
30	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
31	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
32	// for more details.
33	//
34	// You should have received a copy of the GNU General Public License along
35	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
36	// target there if the PDF file isn't present.)  If not, see
37	// <http://www.gnu.org/licenses/> for a copy.
38	// }}}
39	// License:	GPL, v3, as defined and found on www.gnu.org,
40	// {{{
41	//		http://www.gnu.org/licenses/gpl.html
42	//
43	////////////////////////////////////////////////////////////////////////////////
44	//
45	`default_nettype	none
46	// }}}
47	module	pffifo #(
48			// {{{
49			parameter	LGFIFO = 4,
50			parameter	AW = 30,
51			parameter	BUS_WIDTH = 128, // Num data bits on the bus
52			parameter	INSN_WIDTH = 32,
53			parameter [0:0]	OPT_LITTLE_ENDIAN = 1'b0,
54			parameter [0:0]	OPT_LOWPOWER = 1'b0,
55			parameter [0:0]	OPT_ASYNC_READ = (BUS_WIDTH != INSN_WIDTH),
56			localparam	BUSW = BUS_WIDTH,
57			localparam	WBLSB = $clog2(BUS_WIDTH/8),
58			localparam	ADDRESS_WIDTH=AW + WBLSB
59			// }}}
60		) (
61			// {{{
62			input	wire			i_clk, i_reset,
63			//
64			// The interface with the rest of the CPU
65			// {{{
66			input	wire			i_new_pc,
67			input	wire			i_clear_cache,
68			input	wire			i_ready,
69			input wire [ADDRESS_WIDTH-1:0]	i_pc,
70			output	wire			o_valid,
71			output	wire			o_illegal,
72			output	wire [INSN_WIDTH-1:0]	o_insn,
73			output reg [ADDRESS_WIDTH-1:0]	o_pc,
74			// }}}
75			// The wishbone bus interface
76			// {{{
77			output	reg			o_wb_cyc, o_wb_stb,
78			// verilator coverage_off
79			output	wire			o_wb_we,
80			// verilator coverage_on
81			output	reg	[AW-1:0]	o_wb_addr,
82			// verilator coverage_off
83			output	wire	[BUSW-1:0]	o_wb_data,
84			output	wire	[BUSW/8-1:0]	o_wb_sel,
85			// verilator coverage_on
86			//
87			input	wire			i_wb_stall, i_wb_ack, i_wb_err,
88			input	wire	[BUSW-1:0]	i_wb_data
89			// }}}
90			// }}}
91		);
92	
93		// Declarations
94		// {{{
95		localparam	INLSB = $clog2(INSN_WIDTH/8);
96	
97		reg			pending_err;
98		reg	[LGFIFO:0]	wb_pending, pipe_fill;
99		wire	[LGFIFO:0]	w_pipe_fill;
100		wire			pipe_full, last_ack;
101	
102		wire			sfifo_reset, ign_sfifo_full, sfifo_empty,pf_err;
103		wire	[LGFIFO:0]	sfifo_fill;	// Used to start operation
104		wire	[BUS_WIDTH-1:0]	sfifo_word;
105		wire			sfifo_read, pf_last;
106	`ifdef	FORMAL
107		wire	[LGFIFO:0]	f_first_addr, f_second_addr,
108					f_distance_to_first, f_distance_to_second;
109		wire	[BUS_WIDTH:0]	f_first_data, f_second_data;
110		wire			f_first_in_fifo, f_second_in_fifo;
111	
112		wire	[BUS_WIDTH-1:0]	f_wide_data;
113	`endif
114		// }}}
115		////////////////////////////////////////////////////////////////////////
116		//
117		// Request instructions from the bus
118		// {{{
119	
120		// o_wb_cyc, o_wb_stb, o_wb_addr, pending_err
121		// {{{
122		initial	pending_err = 1'b0;
123		initial	{ o_wb_cyc, o_wb_stb } = 2'b00;
124		always @(posedge i_clk)
125		if (sfifo_reset)
126		begin
127			pending_err <= 1'b0;
128			o_wb_cyc <= 1'b0;
129			o_wb_stb <= 1'b0;
130			if (i_new_pc)
131				o_wb_addr <= i_pc[ADDRESS_WIDTH-1:WBLSB];
132			if (i_reset)
133				o_wb_addr <= 0;
134		end else if (o_wb_cyc && i_wb_err)
135		begin
136			pending_err <= 1'b1;
137			o_wb_cyc <= 1'b0;
138			o_wb_stb <= 1'b0;
139			// Verilator lint_off WIDTH
140			o_wb_addr <= o_wb_addr - wb_pending;
141			// Verilator lint_on  WIDTH
142		end else if (o_wb_cyc)
143		begin
144			pending_err <= 1'b0;
145			if (o_wb_stb && !i_wb_stall)
146				o_wb_addr <= o_wb_addr + 1;
147			if (pipe_full && !i_wb_stall)
148				o_wb_stb <= 1'b0;
149			if ((!o_wb_stb || (pipe_full && !i_wb_stall)) && last_ack)
150				o_wb_cyc <= 1'b0;
151		end else if (sfifo_fill[LGFIFO:LGFIFO-1] == 2'b00 && !pending_err)
152		begin
153			o_wb_cyc <= 1'b1;
154			o_wb_stb <= 1'b1;
155			// o_wb_addr == same as before
156		end
157	`ifdef	FORMAL
158		always @(*)
159		if (!i_reset)
160			assert(o_wb_cyc == (o_wb_stb || wb_pending > 0));
161	`endif
162		// }}}
163	
164		// o_wb_sel
165		// {{{
166		generate if (INSN_WIDTH == BUS_WIDTH)
167		begin : GEN_ALWAYS_SEL
168			assign	o_wb_sel = {(BUS_WIDTH/8){1'b1}};
169		end else begin : GEN_WB_SEL
170			reg	[BUS_WIDTH/8-1:0]	r_sel;
171			wire	[WBLSB-INLSB-1:0]	new_shift;
172	
173			assign	new_shift = i_pc[WBLSB-1:INLSB];
174	
175			always @(posedge i_clk)
176			if (i_new_pc)
177			begin
178				if (OPT_LITTLE_ENDIAN)
179				begin
180					r_sel <= {(BUS_WIDTH/8){1'b1}}
181							<< ((INSN_WIDTH/8)*new_shift);
182				end else begin
183					r_sel <= {(BUS_WIDTH/8){1'b1}}
184							>> ((INSN_WIDTH/8)*new_shift);
185				end
186			end else if (o_wb_stb && !i_wb_stall)
187				r_sel <= {(BUS_WIDTH/8){1'b1}};
188	
189			assign	o_wb_sel = r_sel;
190		end endgenerate
191		// }}}
192	
193		// wb_pending: When do we shut off CYC?
194		// {{{
195		initial	wb_pending = 0;
196		always @(posedge i_clk)
197		if (sfifo_reset || i_wb_err)
198			wb_pending <= 0;
199		else case({ (o_wb_stb && !i_wb_stall), (o_wb_cyc && i_wb_ack) })
200		2'b10: wb_pending <= wb_pending + 1;
201		2'b01: wb_pending <= wb_pending - 1;
202		default: begin end
203		endcase
204		// }}}
205	
206		// pipe_fill: When do we shut off STB?
207		// {{{
208		initial	pipe_fill = 0;
209		always @(posedge i_clk)
210		if (sfifo_reset || (o_wb_cyc && i_wb_err))
211			pipe_fill <= 0;
212		else if (!pending_err)
213		case({ (o_wb_stb && !i_wb_stall), o_valid && i_ready && pf_last })
214		2'b10: pipe_fill <= pipe_fill + 1;
215		2'b01: pipe_fill <= pipe_fill - 1;
216		default: begin end
217		endcase
218		// }}}
219	
220		assign	w_pipe_fill = pipe_fill + (o_wb_stb ? 1:0);
221		assign	pipe_full = pending_err || w_pipe_fill[LGFIFO];
222	
223		assign	last_ack = (wb_pending + (o_wb_stb ? 1:0)) == (i_wb_ack ? 1:0);
224		assign	o_wb_we = 1'b0;
225		assign	o_wb_data = {(BUS_WIDTH){1'b0}};
226		// }}}
227		////////////////////////////////////////////////////////////////////////
228		//
229		// Placed returned instructions into a FIFO
230		// {{{
231		////////////////////////////////////////////////////////////////////////
232		//
233		//
234	
235		assign	sfifo_reset = i_reset || i_clear_cache || i_new_pc;
236	
237		sfifo #(
238			.BW(BUS_WIDTH+1), .LGFLEN(LGFIFO),
239			.OPT_ASYNC_READ(OPT_ASYNC_READ)
240		) u_sfifo (
241			.i_clk(i_clk), .i_reset(sfifo_reset),
242			.i_wr(o_wb_cyc && (i_wb_ack || i_wb_err) && !pending_err),
243				.i_data({ i_wb_err, i_wb_data }),
244			.o_full(ign_sfifo_full), .o_fill(sfifo_fill),
245			.i_rd(sfifo_read),
246			.o_data({ pf_err, sfifo_word }),
247			.o_empty(sfifo_empty)
248	`ifdef	FORMAL
249			, .f_first_addr(f_first_addr),
250			.f_second_addr(f_second_addr),
251			.f_first_data(f_first_data),
252			.f_second_data(f_second_data),
253			.f_first_in_fifo(f_first_in_fifo),
254			.f_second_in_fifo(f_second_in_fifo),
255			.f_distance_to_first(f_distance_to_first),
256			.f_distance_to_second(f_distance_to_second)
257	`endif
258		);
259	
260		// }}}
261		////////////////////////////////////////////////////////////////////////
262		//
263		// Unpack wide responses into instructions for the CPU
264		// {{{
265	
266		// o_pc
267		// {{{
268		always @(posedge i_clk)
269		begin
270			if (i_reset)
271				o_pc <= 0;
272			else if (i_new_pc)
273				o_pc <= i_pc;
274			else if (o_valid && i_ready)
275				o_pc <= o_pc + INSN_WIDTH/8;
276	
277			o_pc[$clog2(INSN_WIDTH/8)-1:0] <= 0;
278		end
279		// }}}
280	
281		generate if (BUS_WIDTH == INSN_WIDTH)
282		begin : NO_UNPACKING
283			reg	r_illegal;
284	
285			assign	o_valid = !sfifo_empty;
286			assign	sfifo_read = o_valid && i_ready;
287	
288			assign	o_insn = sfifo_word;
289	
290			// o_illegal
291			// {{{
292			initial	r_illegal = 1'b0;
293			always @(posedge i_clk)
294			if (sfifo_reset)
295				r_illegal <= 1'b0;
296			else if (o_valid && o_illegal)
297				r_illegal <= 1'b1;
298	
299			assign	o_illegal = (pf_err && !sfifo_empty) || r_illegal;
300			// }}}
301	
302			assign	pf_last = 1;
303	`ifdef	FORMAL
304			assign	f_wide_data = sfifo_word;
305	`endif
306		end else begin : UNPACK_BUS
307			// {{{
308			reg				r_valid, r_illegal;
309			reg	[BUS_WIDTH-1:0]		r_data;
310			reg	[WBLSB-INLSB-1:0]	first_shift;
311	
312			// o_valid
313			// {{{
314			initial	r_valid = 1'b0;
315			always @(posedge i_clk)
316			if (sfifo_reset)
317				r_valid <= 1'b0;
318			else if (!o_valid || i_ready)
319				r_valid <= !sfifo_empty || (o_valid && !pf_last);
320	
321			assign	o_valid = r_valid;
322			// }}}
323	
324			// first_shift
325			// {{{
326			always @(posedge i_clk)
327			if (i_reset)
328				first_shift <= 0;
329			else if (i_new_pc)
330				first_shift <= i_pc[WBLSB-1:INLSB];
331			else if (sfifo_read && !sfifo_empty)
332				first_shift <= 0;
333	`ifdef	FORMAL
334			always @(*)
335			if (i_reset)
336			begin
337			end else if (o_valid)
338			begin
339				assert(first_shift == 0);
340			end else if (o_wb_cyc || pipe_fill > 0)
341				assert(first_shift == o_pc[WBLSB-1:INLSB]);
342	`endif
343			// }}}
344	
345			// o_insn
346			// {{{
347			initial	r_data = {(BUS_WIDTH){1'b0}};
348			always @(posedge i_clk)
349			if (OPT_LOWPOWER && (sfifo_reset))
350				r_data <= 0;
351			else if (!o_valid || i_ready)
352			begin
353				if (o_valid && !pf_last)
354				begin
355					if (OPT_LITTLE_ENDIAN)
356						r_data <= r_data >> INSN_WIDTH;
357					else
358						r_data <= r_data << INSN_WIDTH;
359				end else if ((!OPT_LOWPOWER || !sfifo_empty)
360					&& (pf_last || !o_valid))
361				begin
362					if (OPT_LITTLE_ENDIAN)
363						r_data <= sfifo_word >> (INSN_WIDTH * first_shift);
364					else
365						r_data <= sfifo_word << (INSN_WIDTH * first_shift);
366				end
367			end
368	
369			if (OPT_LITTLE_ENDIAN)
370			begin : ASSIGN_LOWBITS
371				assign	o_insn = r_data[INSN_WIDTH-1:0];
372			end else begin : ASSIGN_HIBITS
373				assign	o_insn = r_data[BUS_WIDTH-INSN_WIDTH +: INSN_WIDTH];
374			end
375			// }}}
376	
377			assign	sfifo_read = (!o_valid || i_ready)
378							&& (!o_valid || pf_last);
379	
380			assign	pf_last = (&o_pc[WBLSB-1:INLSB]);
381	
382			// o_illegal
383			// {{{
384			initial	r_illegal = 1'b0;
385			always @(posedge i_clk)
386			if (sfifo_reset)
387				r_illegal <= 1'b0;
388			else if (sfifo_read && !sfifo_empty)
389				r_illegal <= r_illegal || pf_err;
390	
391			assign	o_illegal = r_illegal;
392			// }}}
393	`ifdef	FORMAL
394			assign	f_wide_data = r_data;
395	`endif
396			// }}}
397		end endgenerate
398	
399	
400		// }}}
401	
402		// Keep Verilator happy
403		// {{{
404		// Verilator lint_off UNUSED
405		wire	unused;
406	
407		assign	unused = &{ 1'b0, sfifo_fill[LGFIFO-2:0], ign_sfifo_full };
408		// Verilator lint_on  UNUSED
409		// }}}
410	////////////////////////////////////////////////////////////////////////////////
411	////////////////////////////////////////////////////////////////////////////////
412	////////////////////////////////////////////////////////////////////////////////
413	//
414	// Formal property section
415	// {{{
416	////////////////////////////////////////////////////////////////////////////////
417	////////////////////////////////////////////////////////////////////////////////
418	////////////////////////////////////////////////////////////////////////////////
419	`ifdef	FORMAL
420		// Declarations, reset, and f_past_valid
421		// {{{
422		localparam	F_LGDEPTH=LGFIFO+1;
423	
424		reg			f_past_valid;
425		reg	[4:0]		f_cpu_delay;
426		wire	[WBLSB+AW-1:0]	f_const_addr, f_address;
427		wire			f_const_illegal;
428		wire	[INSN_WIDTH-1:0]	f_const_insn;
429		wire			f_fifo_extra;
430	
431		wire	[(F_LGDEPTH-1):0]	f_nreqs, f_nacks, f_outstanding;
432		wire	[INSN_WIDTH-1:0]	f_insn;
433	
434		(* anyconst *)	reg	[BUS_WIDTH-1:0]		f_const_word;
435		(* anyconst *)	reg	fnvr_err;
436	
437		reg			f_this_return, f_this_fifo;
438		reg	[AW-1:0]	f_return_addr;
439	
440	
441	
442		// Keep track of a flag telling us whether or not $past()
443		// will return valid results
444		initial	f_past_valid = 1'b0;
445		always @(posedge i_clk)
446			f_past_valid <= 1'b1;
447	
448		//
449		// Assume we start from a reset condition
450		always @(*)
451		if (!f_past_valid)
452			assume(i_reset);
453		// }}}
454		////////////////////////////////////////////////////////////////////////
455		//
456		// Assumptions about our inputs
457		// {{{
458		////////////////////////////////////////////////////////////////////////
459		//
460		//
461	
462		ffetch #(
463			// {{{
464			.ADDRESS_WIDTH(AW + WBLSB-INLSB), .OPT_CONTRACT(1'b1),
465			.INSN_WIDTH(INSN_WIDTH)
466			// }}}
467		) fcpu(
468			// {{{
469			.i_clk(i_clk), .i_reset(i_reset),
470			.cpu_new_pc(i_new_pc),
471			.cpu_clear_cache(i_clear_cache),
472			.cpu_pc(i_pc), .cpu_ready(i_ready), .pf_valid(o_valid),
473			.pf_insn(o_insn), .pf_pc(o_pc), .pf_illegal(o_illegal),
474			.fc_pc(f_const_addr), .fc_illegal(f_const_illegal),
475			.fc_insn(f_const_insn), .f_address(f_address)
476			// }}}
477		);
478	
479		always @(*)
480		begin
481			assume(f_address[INLSB-1:0] == 0);
482		end
483	
484		always @(*)
485		begin
486			f_return_addr = o_wb_addr - wb_pending;
487			f_this_return = (f_return_addr == f_const_addr[WBLSB +: AW]);
488		end
489	
490		always @(*)
491		if (f_this_return)
492		begin
493			if (f_const_illegal)
494				assume(!i_wb_ack);
495			else
496				assume(!i_wb_err);
497	
498			if (i_wb_ack)
499				assume(i_wb_data == f_const_word);
500		end
501	
502		// f_const_word -- a wide bus word to check against
503		// {{{
504		generate if (INSN_WIDTH == BUS_WIDTH)
505		begin : F_CONST_NOSHIFT
506			always @(*)
507				assume(f_const_word == f_const_insn);
508		end else begin : F_CONST_SHIFT
509	
510			wire	[WBLSB-INLSB-1:0]	f_shift, f_shift_now;
511			wire	[BUS_WIDTH-1:0]		f_shifted, f_now;
512			wire	[INSN_WIDTH-1:0]	f_insn_check, f_insn_now;
513			wire		f_now_check;
514	
515			assign	f_shift = f_const_addr[WBLSB-1:INLSB];
516			assign	f_shift_now = f_const_addr[WBLSB-1:INLSB] - o_pc[WBLSB-1:INLSB];
517	
518			if (OPT_LITTLE_ENDIAN)
519			begin
520				assign	f_shifted = f_const_word >> (INSN_WIDTH * f_shift);
521				assign	f_insn_check = f_shifted[INSN_WIDTH-1:0];
522	
523	
524				assign	f_now = f_wide_data >> (INSN_WIDTH * f_shift_now);
525				assign	f_insn_now = f_now[INSN_WIDTH-1:0];
526			end else begin
527				assign	f_shifted = f_const_word << (INSN_WIDTH * f_shift);
528				assign	f_insn_check = f_shifted[BUS_WIDTH-1:BUS_WIDTH-INSN_WIDTH];
529	
530				assign	f_now = f_wide_data << (INSN_WIDTH * f_shift_now);
531				assign	f_insn_now = f_now[BUS_WIDTH-1:BUS_WIDTH-INSN_WIDTH];
532			end
533	
534			assign	f_now_check = o_valid && !o_illegal
535					&& o_pc[WBLSB +: AW]==f_const_addr[WBLSB +: AW]
536					&& f_const_addr[WBLSB-1:INLSB] >= o_pc[WBLSB-1:INLSB];
537	
538			always @(*)
539				assume(f_insn_check == f_const_insn);
540	
541			always @(*)
542			if (f_past_valid && f_now_check)
543				assert(f_insn_now == f_const_insn);
544	
545		end endgenerate
546		// }}}
547	
548	`ifdef	SKIPME
549		// {{{
550		// Let's make some assumptions about how long it takes our
551		// phantom bus and phantom CPU to respond.
552		//
553		// These delays need to be long enough to flush out any potential
554		// errors, yet still short enough that the formal method doesn't
555		// take forever to solve.
556		//
557		localparam	F_CPU_DELAY = 4;
558	
559	
560		// Now, let's repeat this bit but now looking at the delay the CPU
561		// takes to accept an instruction.
562		always @(posedge i_clk)
563		// If no instruction is ready, then keep our counter at zero
564		if ((!o_valid)||(i_ready))
565			f_cpu_delay <= 0;
566		else
567			// Otherwise, count the clocks the CPU takes to respond
568			f_cpu_delay <= f_cpu_delay + 1'b1;
569	
570	`ifdef	PFCACHE
571		always @(posedge i_clk)
572			assume(f_cpu_delay < F_CPU_DELAY);
573	`endif
574		// }}}
575	`else
576		always @(*)
577			f_cpu_delay = 0;
578	`endif
579		// }}}
580		////////////////////////////////////////////////////////////////////////
581		//
582		// FIFO checks
583		// {{{
584		////////////////////////////////////////////////////////////////////////
585		//
586		//
587		reg	[AW-1:0]	fifo_addr, f_first_wbaddr, f_second_wbaddr;
588		reg			f_first_is_last, f_second_is_last,
589					f_known_return;
590	
591		assign	f_fifo_extra = o_valid && (INSN_WIDTH != BUS_WIDTH);
592	
593		// Relating o_pc to o_wb_addr
594		always @(*)
595		begin
596			if (pending_err)
597				fifo_addr = o_pc[WBLSB +: AW] + (f_fifo_extra ? 1:0);
598			else begin
599				fifo_addr = o_wb_addr - pipe_fill;
600				if (f_fifo_extra)
601					fifo_addr = fifo_addr + 1;
602			end
603	
604			f_this_fifo = !sfifo_empty
605					&& (fifo_addr == f_const_addr[WBLSB +: AW]);
606	
607			f_first_wbaddr  = o_pc[WBLSB +: AW] + f_distance_to_first;
608			f_second_wbaddr = o_pc[WBLSB +: AW] + f_distance_to_second;
609	
610			if(f_fifo_extra)
611			begin
612				f_first_wbaddr  = f_first_wbaddr  + 1;
613				f_second_wbaddr = f_second_wbaddr + 1;
614			end
615	
616			f_first_is_last = (f_distance_to_first + 1 == sfifo_fill);
617			f_second_is_last = (f_distance_to_second + 1 == sfifo_fill);
618	
619			f_known_return = (f_first_in_fifo && f_distance_to_first==0)
620				|| (f_second_in_fifo && f_distance_to_second == 0);
621		end
622	
623		always @(*)
624		if (f_past_valid && (o_valid || o_wb_cyc || sfifo_fill > 0))
625			assert(o_pc == f_address);
626	
627		always @(*)
628		if (!sfifo_reset && !o_illegal && !pending_err)
629			assert(o_pc[WBLSB +: AW] == fifo_addr - f_fifo_extra);
630	
631		always @(*)
632		if (f_past_valid)
633		begin
634			if (f_first_in_fifo&& !o_illegal && f_first_wbaddr
635							== f_const_addr[WBLSB +: AW])
636			begin
637				if (f_const_illegal)
638					assert(f_first_data[BUS_WIDTH]);
639				else
640					assert(f_first_data== { 1'b0,f_const_word });
641			end
642	
643			if (f_second_in_fifo&& !o_illegal && f_second_wbaddr
644							== f_const_addr[WBLSB +: AW])
645			begin
646				if (f_const_illegal)
647					assert(f_second_data[BUS_WIDTH]);
648				else
649					assert(f_second_data=={ 1'b0,f_const_word });
650			end
651	
652			if (f_first_in_fifo && !f_first_is_last)
653				assert(!f_first_data[BUS_WIDTH]);
654			if (f_second_in_fifo && !f_second_is_last)
655				assert(!f_second_data[BUS_WIDTH]);
656			if (!f_known_return)
657			begin
658				if (sfifo_fill > 1)
659					assume(!pf_err);
660				if (!pending_err)
661					assume(!pf_err);
662				if (f_this_fifo)
663				begin
664					if (f_const_illegal)
665						assume(pf_err);
666					else
667						assume(!pf_err && sfifo_word == f_const_word);
668				end
669			end
670	
671			if (!pending_err)
672				assert(!o_illegal);
673			if (o_valid && f_const_addr[WBLSB +: AW] == o_pc[WBLSB +: AW])
674			begin
675				if (f_const_illegal)
676					assert(o_illegal);
677			end
678	
679			if (pending_err)
680			begin
681				if (f_first_in_fifo && f_first_is_last)
682				begin
683					assert(f_first_data[BUS_WIDTH]);
684				end else if (f_second_in_fifo && f_second_is_last)
685				begin
686					assert(f_second_data[BUS_WIDTH]);
687				end else if (sfifo_fill == 1)
688					assume(pf_err);
689			end else begin
690				if (f_first_in_fifo)
691					assert(!f_first_data[BUS_WIDTH]);
692				if (f_second_in_fifo)
693					assert(!f_second_data[BUS_WIDTH]);
694			end
695		end
696	
697		// }}}
698		////////////////////////////////////////////////////////////////////////
699		//
700		// Assertions about our outputs
701		// {{{
702		////////////////////////////////////////////////////////////////////////
703		//
704		//
705	
706		fwb_master #(
707			// {{{
708			.AW(AW), .DW(BUSW), .F_LGDEPTH(F_LGDEPTH),
709			.F_MAX_STALL(2), .F_MAX_ACK_DELAY(3),
710			.F_MAX_REQUESTS(0), .F_OPT_SOURCE(1),
711			.F_OPT_RMW_BUS_OPTION(0),
712			.F_OPT_DISCONTINUOUS(0)
713			// }}}
714		) f_wbm(
715			// {{{
716			.i_clk(i_clk), .i_reset(i_reset),
717			.i_wb_cyc(o_wb_cyc), .i_wb_stb(o_wb_stb),
718			.i_wb_we(o_wb_we), .i_wb_addr(o_wb_addr),
719				.i_wb_data(o_wb_data), .i_wb_sel(o_wb_sel),
720			.i_wb_ack(i_wb_ack), .i_wb_stall(i_wb_stall),
721				.i_wb_data(i_wb_data), .i_wb_err(i_wb_err),
722			.f_nreqs(f_nreqs), .f_nacks(f_nacks),
723				.f_outstanding(f_outstanding)
724			// }}}
725		);
726	
727		always @(*)
728		if (fnvr_err)
729			assume(!i_wb_err);
730	
731		always @(*)
732		if (!i_reset && fnvr_err)
733		begin
734			assert(!pending_err);
735			assert(!o_illegal);
736		end
737	
738		// writes are also illegal for a prefetch.
739		always @(posedge i_clk)
740		if (o_wb_stb)
741			assert(!o_wb_we);
742	
743		always @(posedge i_clk)
744		begin
745			assert(f_outstanding == wb_pending);
746			assert(pipe_fill >= wb_pending);
747			if (!pending_err)
748			begin
749				assert(pipe_fill >= sfifo_fill);
750				assert(pipe_fill == sfifo_fill + wb_pending + f_fifo_extra);
751			end
752			assert(pipe_fill <= (1<<LGFIFO));
753		end
754	
755		// }}}
756		////////////////////////////////////////////////////////////////////////
757		//
758		// Assertions about our return responses to the CPU
759		// {{{
760		////////////////////////////////////////////////////////////////////////
761		//
762		//
763	
764		always @(*)
765		if (!sfifo_reset)
766			assert(o_illegal || o_pc == f_address);
767	
768		//
769		// If an instruction is accepted, we should *always* move on to another
770		// instruction.  The only exception is following an i_new_pc (or
771		// other invalidator), at which point the next instruction should
772		// be invalid.
773		always @(posedge i_clk)
774		if ((f_past_valid)&& $past(o_valid && i_ready && !o_illegal && !i_new_pc))
775		begin
776			// Should always advance the instruction pointer
777			assert((!o_valid)||(o_pc != $past(o_pc)));
778		end
779	
780		//
781		// Once an instruction becomes valid, it should never become invalid
782		// unless there's been a request for a new instruction.
783		always @(posedge i_clk)
784		if (!f_past_valid || $past(sfifo_reset))
785		begin
786			assert(!o_valid);
787			assert(!o_illegal);
788		end else if ($past(o_valid && !i_ready))
789		begin
790			if (!$past(o_illegal))
791			begin
792				assert(o_valid);
793				assert(!o_illegal);
794				assert($stable(o_insn));
795			end else
796				assert(o_illegal);
797		end
798		// }}}
799		////////////////////////////////////////////////////////////////////////
800		//
801		// Cover properties
802		// {{{
803		////////////////////////////////////////////////////////////////////////
804		//
805		//
806	
807		reg	f_valid_legal;
808		always @(*)
809			f_valid_legal = o_valid && (!o_illegal);
810		always @(posedge i_clk)		// Trace 0
811			cover((o_valid)&&( o_illegal));
812		always @(posedge i_clk)		// Trace 1
813			cover(f_valid_legal);
814		always @(posedge i_clk)		// Trace 2
815			cover((f_valid_legal)
816				&&($past(!o_valid && !i_new_pc))
817				&&($past(i_new_pc,4)));
818		always @(posedge i_clk)
819			cover((f_valid_legal)&&($past(f_valid_legal && i_ready)));
820		always @(posedge i_clk)
821			cover((f_valid_legal)
822				&&($past(f_valid_legal && i_ready))
823				&&($past(f_valid_legal && i_ready,2))
824				&&($past(f_valid_legal && i_ready,3)));
825		always @(posedge i_clk)
826			cover((f_valid_legal)
827				&&($past(f_valid_legal && i_ready))
828				&&($past(f_valid_legal && i_ready,2))
829				&&($past(!o_illegal && i_ready && i_new_pc,5))
830				&&($past(f_valid_legal && i_ready,6)));
831		// }}}
832	`endif	// FORMAL
833	// }}}
834	endmodule
835

